"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["3189"],{9511(e,n,i){i.r(n),i.d(n,{metadata:()=>r,default:()=>u,frontMatter:()=>d,contentTitle:()=>a,toc:()=>h});var r=JSON.parse('{"docId":"references/paper","permalink":"/de-DE/docs/references/paper","source":"@site/i18n/de-DE/lagune-docs-content/references/paper.mdx","title":"Security-Driven Hardening: eine Konvention f\xfcr das Zeitalter der KI-gest\xfctzten Entwicklung","sidebarLabel":"Methodenpapier","description":"Die Methodik Security-Driven Hardening (SDH): eine kontextbezogene Blue-Team-Konvention f\xfcr das Auditieren und H\xe4rten von Software, die mit KI-Unterst\xfctzung oder per Vibe Coding entsteht.","keywords":["Security-Driven Hardening","SDH","defensive Sicherheit","H\xe4rtung","hardening","spec-driven development","Lagune Methodenpapier"],"datePublished":"2026-11-03T17:10:11.000Z","dateModified":"2026-11-03T17:10:11.000Z","state":"translated","alternates":[{"locale":"en","permalink":"/docs/references/paper"},{"locale":"pt-BR","permalink":"/pt-BR/docs/references/paper"},{"locale":"zh-CN","permalink":"/zh-CN/docs/references/paper"},{"locale":"ja-JP","permalink":"/ja-JP/docs/references/paper"},{"locale":"es-ES","permalink":"/es-ES/docs/references/paper"},{"locale":"de-DE","permalink":"/de-DE/docs/references/paper"}]}'),t=i(4848),s=i(8453);let d={id:"paper",title:"Security-Driven Hardening: eine Konvention f\xfcr das Zeitalter der KI-gest\xfctzten Entwicklung",sidebar_label:"Methodenpapier",description:"Die Methodik Security-Driven Hardening (SDH): eine kontextbezogene Blue-Team-Konvention f\xfcr das Auditieren und H\xe4rten von Software, die mit KI-Unterst\xfctzung oder per Vibe Coding entsteht.",keywords:["Security-Driven Hardening","SDH","defensive Sicherheit","H\xe4rtung","hardening","spec-driven development","Lagune Methodenpapier"],source_hash:"d5c17c54275231730b67910e0da9a868319b7d5d31ba953ac5756a606bed5cb6"},a="Security-Driven Hardening (SDH): eine Konvention f\xfcr das Zeitalter der KI-gest\xfctzten Entwicklung",h=[{value:"Zusammenfassung",id:"zusammenfassung",level:2},{value:"I. Einleitung: die Sicherheitsl\xfccke, die KI-gest\xfctzte Entwicklung ge\xf6ffnet hat",id:"i-einleitung-die-sicherheitsl\xfccke-die-ki-gest\xfctzte-entwicklung-ge\xf6ffnet-hat",level:2},{value:"II. Hintergrund und verwandte Arbeiten",id:"ii-hintergrund-und-verwandte-arbeiten",level:2},{value:"III. SDH: Definition und Gestaltungsprinzipien",id:"iii-sdh-definition-und-gestaltungsprinzipien",level:2},{value:"IV. Der Blue-Team-Workflow in 5 Phasen",id:"iv-der-blue-team-workflow-in-5-phasen",level:2},{value:"charter (Richtlinie)",id:"charter-richtlinie",level:3},{value:"detect (Erkennung)",id:"detect-erkennung",level:3},{value:"plan (Triage)",id:"plan-triage",level:3},{value:"harden (Behebung)",id:"harden-behebung",level:3},{value:"verify (Verifizierung)",id:"verify-verifizierung",level:3},{value:"V. Abschlie\xdfbarkeit: Ein Befund hat einen Endzustand",id:"v-abschlie\xdfbarkeit-ein-befund-hat-einen-endzustand",level:2},{value:"VI. Die Dualit\xe4t als Erweiterung des Entwicklerwissens",id:"vi-die-dualit\xe4t-als-erweiterung-des-entwicklerwissens",level:2},{value:"VII. Nicht aufrufbare Spezialisierungen und Prompt bei Bedarf",id:"vii-nicht-aufrufbare-spezialisierungen-und-prompt-bei-bedarf",level:2},{value:"VIII. Zustandsunabh\xe4ngigkeit und nicht vorschreibende Anpassungsf\xe4higkeit",id:"viii-zustandsunabh\xe4ngigkeit-und-nicht-vorschreibende-anpassungsf\xe4higkeit",level:2},{value:"Zustandsunabh\xe4ngigkeit",id:"zustandsunabh\xe4ngigkeit",level:3},{value:"Nicht vorschreibende Anpassungsf\xe4higkeit",id:"nicht-vorschreibende-anpassungsf\xe4higkeit",level:3},{value:"IX. Der universelle pr\xe4ventive Modus: dieselbe Verteidigung, w\xe4hrend die Arbeit entsteht",id:"ix-der-universelle-pr\xe4ventive-modus-dieselbe-verteidigung-w\xe4hrend-die-arbeit-entsteht",level:2},{value:"X. Security-Driven Hardening im Vergleich zu Spec-Driven Development",id:"x-security-driven-hardening-im-vergleich-zu-spec-driven-development",level:2},{value:"XI. Technische Sorgfalt: die Disziplin der Nachverfolgung",id:"xi-technische-sorgfalt-die-disziplin-der-nachverfolgung",level:2},{value:"XII. Der Tr\xe4ger: agentenunabh\xe4ngige Architektur als Nachweis der Portabilit\xe4t",id:"xii-der-tr\xe4ger-agentenunabh\xe4ngige-architektur-als-nachweis-der-portabilit\xe4t",level:2},{value:"XIII. Fallbeispiel: SDH von Anfang bis Ende",id:"xiii-fallbeispiel-sdh-von-anfang-bis-ende",level:2},{value:"XIV. Wann sich SDH eignet und wo seine Grenzen liegen",id:"xiv-wann-sich-sdh-eignet-und-wo-seine-grenzen-liegen",level:2},{value:"XV. Diskussion: Einordnung, Grenzen und was SDH nicht behauptet",id:"xv-diskussion-einordnung-grenzen-und-was-sdh-nicht-behauptet",level:2},{value:"Es erweitert, es ersetzt nicht",id:"es-erweitert-es-ersetzt-nicht",level:3},{value:"Ausschlie\xdflich defensiv, vom Aufbau her",id:"ausschlie\xdflich-defensiv-vom-aufbau-her",level:3},{value:"Die Verifizierung ist substanziell, nicht theatralisch",id:"die-verifizierung-ist-substanziell-nicht-theatralisch",level:3},{value:"Determinismus ist begrenzt und benannt",id:"determinismus-ist-begrenzt-und-benannt",level:3},{value:"Kosten und Skalierung",id:"kosten-und-skalierung",level:3},{value:"Der Nutzer hat das letzte Wort",id:"der-nutzer-hat-das-letzte-wort",level:3},{value:"Einw\xe4nde und Antworten",id:"einw\xe4nde-und-antworten",level:3},{value:"XVI. Fallstricke und wie SDH sie strukturell vermeidet",id:"xvi-fallstricke-und-wie-sdh-sie-strukturell-vermeidet",level:2},{value:"XVII. K\xfcnftige Arbeiten",id:"xvii-k\xfcnftige-arbeiten",level:2},{value:"XVIII. Fazit",id:"xviii-fazit",level:2},{value:"Literatur",id:"literatur",level:2},{value:"Anhang A: die Prinzipien im Wortlaut",id:"anhang-a-die-prinzipien-im-wortlaut",level:2}];function l(e){let n={a:"a",blockquote:"blockquote",code:"code",em:"em",h2:"h2",h3:"h3",hr:"hr",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:(0,t.jsx)(n.strong,{children:"Weslley Ara\xfajo"})}),"\n",(0,t.jsx)(n.li,{children:(0,t.jsx)(n.strong,{children:"Methodenpapier, 2026."})}),"\n"]}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"zusammenfassung",children:"Zusammenfassung"}),"\n",(0,t.jsx)(n.p,{children:"Security-Driven Hardening (SDH) ist eine strukturierte, KI-gesteuerte und ausschlie\xdflich defensive Sicherheitsmethodik f\xfcr eine Zeit, in der Software zunehmend von KI-Agenten und von Menschen geschrieben wird, die keine Sicherheitsfachleute sind. Statt eine generische Checkliste abzuarbeiten, erkennt SDH zuerst, was ein System tats\xe4chlich tut (Anmeldung, Datei-Uploads, Zahlungen, Offenlegung von Daten und so weiter), und steuert dann die Sicherheitsarbeit, die genau zu diesem Kontext passt. Standardm\xe4\xdfig sichere Prinzipien geben den Rahmen vor, die Methodik ist vollst\xe4ndig auf Verteidigung ausgerichtet und in verst\xe4ndlicher Sprache formuliert, damit jeder Nutzer danach handeln kann."}),"\n",(0,t.jsxs)(n.p,{children:["Dieses Dokument vertritt die These, dass SDH eine fehlende Konvention ist, kein einzelnes Werkzeug. Das Sicherheitswissen steckt in der Methodik und ihren bei Bedarf geladenen Spezialisierungen, einer Grundlage, auf der jeder Nutzer aufbauen kann, und so dient derselbe Workflow einem Einsteiger wie einem Experten. Zwei Eigenschaften unterscheiden SDH von fr\xfcheren Spec-first-Ans\xe4tzen ",(0,t.jsx)(n.code,{children:"[1]"}),". SDH ist ",(0,t.jsx)(n.strong,{children:"zustandsunabh\xe4ngig"}),": Es passt sich an ein leeres Verzeichnis, ein laufendes Projekt, einen einzelnen Pull Request oder eine gro\xdfe Legacy-Codebasis an, in jedem Stack. Und SDH ist ",(0,t.jsx)(n.strong,{children:"abschlie\xdfbar"}),": Ein als geschlossen verifiziertes Risiko wird aus dem gesamten Workflow ausgetragen, sodass dieser Befund in den Ruhezustand \xfcbergeht und erst wieder ge\xf6ffnet wird, wenn sich der Code \xe4ndert. SDH ersetzt weder Sicherheitsfachleute noch spezialisierte Blue-Team-Werkzeuge. Es erweitert das Wissen der Entwickler selbst, und je mehr ein Entwickler von Sicherheit versteht, desto mehr kann er es steuern."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Lagune"})," ist die Referenzimplementierung und belegt, dass sich die Methodik umsetzen und \xfcbertragen l\xe4sst. SDH versteht sich als Konvention, die andere \xfcbernehmen k\xf6nnen."]}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Schlagw\xf6rter"})}),"\n",(0,t.jsx)(n.p,{children:"KI-gest\xfctzte Entwicklung, Softwaresicherheit, defensive Sicherheit, spec-driven development, Security Hardening, agentengesteuerte Workflows, Abschlie\xdfbarkeit, kontextbezogene Sicherheit, Wissen bei Bedarf, agentenunabh\xe4ngige Werkzeuge."}),"\n"]}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"i-einleitung-die-sicherheitsl\xfccke-die-ki-gest\xfctzte-entwicklung-ge\xf6ffnet-hat",children:"I. Einleitung: die Sicherheitsl\xfccke, die KI-gest\xfctzte Entwicklung ge\xf6ffnet hat"}),"\n",(0,t.jsxs)(n.p,{children:["Immer mehr Software stammt von Menschen, und von KI-Agenten, die ein unsicheres Muster nicht zuverl\xe4ssig erkennen: ein geleaktes Secret, eine fehlende Autorisierungspr\xfcfung, eine f\xfcr Injection anf\xe4llige Abfrage. Das sind keine exotischen Risiken. Sie geh\xf6ren zu den Risikoklassen, die reale Vorf\xe4lle dominieren und seit Jahren in \xf6ffentlichen Referenzen dokumentiert sind ",(0,t.jsx)(n.code,{children:"[6]"}),", ",(0,t.jsx)(n.code,{children:"[7]"}),", und aktuelle Studien zeigen, dass ein nennenswerter Anteil des KI-generierten Codes genau mit solchen M\xe4ngeln ausgeliefert wird ",(0,t.jsx)(n.code,{children:"[8]"}),'. KI-Programmierassistenten haben das versch\xe4rft, weil sie auch Nicht-Entwicklern erm\xf6glichen, echte Software auszuliefern, doch die L\xfccke reicht \xfcber jede einzelne Zielgruppe hinaus. Die meisten Projekte bekommen nie eine Sicherheitspr\xfcfung, die auf das zugeschnitten ist, was sie tats\xe4chlich tun. Mit jeder vorschnellen Entscheidung nach dem Motto "l\xe4uft, raus damit" wird das \xd6kosystem fragiler.']}),"\n",(0,t.jsx)(n.p,{children:"Generische Sicherheitsratschl\xe4ge schlie\xdfen diese L\xfccke nicht. Eine statische Checkliste ist nicht auf das zugeschnitten, was ein System tut, deshalb \xfcberschwemmt sie ein kleines Projekt mit irrelevanten Punkten und \xfcbersieht trotzdem das Risiko, auf das es bei genau diesem Projekt ankommt. Das Problem ist nicht, dass es auf der Welt zu wenig Sicherheitswissen g\xe4be. Das Problem ist, das passende Wissen dem System zuzuordnen, das tats\xe4chlich vor dem Nutzer liegt, und das f\xfcr jemanden, der vielleicht nicht wei\xdf, wonach er fragen soll."}),"\n",(0,t.jsxs)(n.p,{children:["SDH antwortet darauf mit einer einzigen Umkehrung: ",(0,t.jsx)(n.strong,{children:"Das Sicherheitswissen steckt in der Spezifikation und ihren bei Bedarf geladenen Spezialisierungen, einer Grundlage, auf der jeder Nutzer aufbauen kann"}),". Die Methodik erkennt den Kontext, priorisiert die Risiken, die dieser Kontext mit sich bringt, und leitet die Korrekturen an, sodass Entwickler und Nicht-Entwickler denselben Workflow nutzen. Befunde und Empfehlungen bleiben in verst\xe4ndlicher Sprache, damit man unabh\xe4ngig vom technischen Vorwissen danach handeln kann. Den Experten schr\xe4nkt das nicht ein, sondern verst\xe4rkt ihn, eine Dualit\xe4t, die wir in ",(0,t.jsx)(n.code,{children:"\xa7VI"})," ausf\xfchren."]}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Kernaussage"})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Die zentrale Umkehrung:"})," Das Sicherheitswissen steckt in der Spezifikation und ihren bei Bedarf geladenen Spezialisierungen, einer Grundlage, auf der jeder Nutzer aufbauen kann. Die Methodik lernt, was das System tut, stimmt die Sicherheitsarbeit darauf ab und erweitert, was der Nutzer bereits wei\xdf."]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:'Angenommen, ein Entwickler sagt zu einem KI-Assistenten: "Meine App l\xe4sst Nutzer ein Profilbild hochladen." Ohne Sicherheitspr\xfcfung liefert der Assistent funktionierenden Code, der stillschweigend allem vertraut, was der Client schickt: dem angegebenen Dateityp, dem Dateinamen, der Gr\xf6\xdfe. Der Upload geht live, und eine als Bild getarnte Datei kann Code enthalten, ein manipulierter Name kann aus dem Speicherpfad ausbrechen, eine \xfcbergro\xdfe Datei kann den Server lahmlegen. Nichts davon ist in einer Demo zu sehen, also wird es ausgeliefert.'}),"\n",(0,t.jsx)(n.p,{children:'Derselbe Code verh\xe4lt sich mit SDH anders. SDH erkennt, dass das System Dateien von au\xdfen annimmt (Erkennung), leitet daraus die Risiken ab, die ein Upload mit sich bringt (Triage), schl\xe4gt vor, den echten Dateityp und die Gr\xf6\xdfe zu pr\xfcfen, die Datei beim Speichern umzubenennen und sie dort abzulegen, wo kein Code ausgef\xfchrt werden kann (Behebung), liest dann das Ergebnis und best\xe4tigt, dass jede Schutzma\xdfnahme tats\xe4chlich greift (Verifizierung). Der Entwickler musste den Begriff "uneingeschr\xe4nkter Datei-Upload" nie kennen. Die Methodik hat ihn an seiner Stelle eingebracht.'}),"\n",(0,t.jsx)(n.p,{children:"Dieses Dokument leistet folgende Beitr\xe4ge:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["Eine pr\xe4zise Definition von SDH als Methodik, unabh\xe4ngig von einer bestimmten Implementierung, samt ihren Gestaltungsprinzipien (",(0,t.jsx)(n.code,{children:"\xa7III"}),")."]}),"\n",(0,t.jsxs)(n.li,{children:["Ein defensiver Lebenszyklus in f\xfcnf Phasen, in dem die Aufgabentrennung selbst der Beitrag ist: Die Erkennung erfindet nie etwas, die Planung liest nie Code, nur eine Phase \xe4ndert Code, und die Verifizierung schw\xe4cht ihr Urteil nie ab (",(0,t.jsx)(n.code,{children:"\xa7IV"}),")."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Abschlie\xdfbarkeit"})," als methodische Haltung: Ein einzelner Befund hat einen Endzustand statt einer Endlosschleife (",(0,t.jsx)(n.code,{children:"\xa7V"}),")."]}),"\n",(0,t.jsxs)(n.li,{children:["Die Dualit\xe4t als ",(0,t.jsx)(n.strong,{children:"Erweiterung des Entwicklerwissens"}),": ein Workflow, der den Einsteiger sch\xfctzt und den Experten verst\xe4rkt (",(0,t.jsx)(n.code,{children:"\xa7VI"}),")."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Nicht aufrufbare Spezialisierungen und Prompt bei Bedarf"}),": fokussiertes Sicherheitswissen, das der Agent l\xe4dt, wenn der Kontext des Projekts es verlangt, nie standardm\xe4\xdfig (",(0,t.jsx)(n.code,{children:"\xa7VII"}),")."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Zustandsunabh\xe4ngigkeit"})," und ",(0,t.jsx)(n.strong,{children:"nicht vorschreibende Anpassungsf\xe4higkeit"}),": SDH passt in jeden Entwicklungsstand und richtet sich nach dem Szenario, statt einen festen Umfang vorzugeben (",(0,t.jsx)(n.code,{children:"\xa7VIII"}),")."]}),"\n",(0,t.jsxs)(n.li,{children:["Ein ",(0,t.jsx)(n.strong,{children:"pr\xe4ventiver Modus"}),": dieselbe Verteidigung, w\xe4hrend die allt\xe4gliche Arbeit entsteht, sodass der Code von Anfang an standardm\xe4\xdfig sicher ist und die Phasen weniger korrigieren m\xfcssen (",(0,t.jsx)(n.code,{children:"\xa7IX"}),")."]}),"\n",(0,t.jsxs)(n.li,{children:["Ein eigener Vergleich mit Spec-Driven Development, der Linie, aus der SDH hervorgegangen ist und von der es sich dann gel\xf6st hat (",(0,t.jsx)(n.code,{children:"\xa7X"}),")."]}),"\n",(0,t.jsxs)(n.li,{children:["Die technischen Disziplinen, mit denen die Methodik Refactorings \xfcbersteht und von jedem Agenten unabh\xe4ngig bleibt: Nachverfolgung mit Identit\xe4t \xfcber den Namen (",(0,t.jsx)(n.code,{children:"\xa7XI"}),") und ein agentenunabh\xe4ngiger Tr\xe4ger (",(0,t.jsx)(n.code,{children:"\xa7XII"}),")."]}),"\n"]}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"ii-hintergrund-und-verwandte-arbeiten",children:"II. Hintergrund und verwandte Arbeiten"}),"\n",(0,t.jsxs)(n.p,{children:["SDH baut auf fr\xfcheren Arbeiten auf. Es \xfcbernimmt eine bew\xe4hrte Struktur aus der agentengesteuerten Spec-first-Entwicklung ",(0,t.jsx)(n.code,{children:"[1]"}),", ",(0,t.jsx)(n.code,{children:"[2]"}),", ",(0,t.jsx)(n.code,{children:"[3]"}),": Vorlagen, Slash-Befehle, die ein Agent verarbeitet, ein \xfcbergeordnetes Dokument und einen Agenten, der die Phasen ausf\xfchrt. Diese Struktur setzt es mit defensivem Zweck neu um. Die Herkunft ist gewollt, und eines der Arbeitsprinzipien von SDH benennt sie direkt: den Workflow auf einer bew\xe4hrten Struktur aufbauen und ihn dann auf Sicherheit ausrichten."]}),"\n",(0,t.jsx)(n.p,{children:"SDH ist keine statische Checkliste generischer Empfehlungen. Eine Checkliste wei\xdf viel \xfcber Sicherheit im Allgemeinen und nichts \xfcber das Projekt vor ihr. SDH kehrt diese Gewichtung um. Es steckt seinen ersten Aufwand in die Erkennung, also darin, zu lernen, was das System tut, und greift erst dann zu dem Wissen, das durch die Erkennung relevant wird."}),"\n",(0,t.jsxs)(n.p,{children:["SDH ersetzt auch keine Sicherheitsfachleute und keine spezialisierten Blue-Team-Werkzeuge. Es erweitert das Wissen der Entwickler (",(0,t.jsx)(n.code,{children:"\xa7VI"}),"). Ein Team mit eigener Sicherheitsabteilung sollte sie behalten. SDH gibt diesem Team einen strukturierten Tr\xe4ger, und einem Team ohne eine solche Abteilung eine belastbare Grundlage."]}),"\n",(0,t.jsxs)(n.p,{children:["SDH steht au\xdferdem neben deterministischen Sicherheitsscannern (statische Analyse, Linter) ",(0,t.jsx)(n.code,{children:"[4]"}),", ",(0,t.jsx)(n.code,{children:"[5]"}),". Diese Werkzeuge sind gerade deshalb wertvoll, weil sie deterministisch und wiederholbar sind. SDH beruht \xfcberwiegend auf dem Schlussfolgern des Agenten und tauscht strengen Determinismus gegen Kontextbezug. Die Methodik gibt auch nicht vor, es w\xe4re anders. Wo Determinismus z\xe4hlt, bettet sie eine deterministische Engine in das Schlussfolgern ein (",(0,t.jsx)(n.code,{children:"\xa7VII"}),"): Der Agent entscheidet, ob es sich lohnt, eine Eingabe zu pr\xfcfen, und ein deterministisches Programm entscheidet, ob diese Eingabe gef\xe4hrlich ist."]}),"\n",(0,t.jsxs)(n.p,{children:["Der direkteste Vorl\xe4ufer ist Spec-Driven Development (SDD), die Familie der Spec-first-Methodiken, die eine Entwicklung von einer ausf\xfchrbaren Spezifikation aus vorantreibt. Wir behandeln SDD als Klasse. Seine klarste Darstellung als Praxismethodik ist der Bericht von Piskala ",(0,t.jsx)(n.code,{children:"[1]"}),", sein sichtbarstes agentengesteuertes Toolkit ist Spec Kit von GitHub ",(0,t.jsx)(n.code,{children:"[2]"}),", und OpenSpec ",(0,t.jsx)(n.code,{children:"[3]"})," ist ein zweites Werkzeug aus derselben Familie. Damit sind die ma\xdfgeblichen Referenzen f\xfcr den Vergleich in ",(0,t.jsx)(n.code,{children:"\xa7X"})," benannt."]}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"iii-sdh-definition-und-gestaltungsprinzipien",children:"III. SDH: Definition und Gestaltungsprinzipien"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Security-Driven Hardening"})," ist eine strukturierte, KI-gesteuerte Sicherheitsmethodik, die eine Codebasis sicherer macht, indem sie die Arbeit von einer Spezifikation aus steuert, die der Agent ausf\xfchrt, statt von spontanen Korrekturen. Der Name ist von den ",(0,t.jsx)(n.strong,{children:"Blue Teams"})," inspiriert, den Verteidigern im Sicherheitsbereich. Bei SDH geht es um Verteidigung, H\xe4rtung und Verifizierung, nie um Angriff."]}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Definition"})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Security-Driven Hardening (SDH):"})," Eine strukturierte, KI-gesteuerte, ausschlie\xdflich defensive Sicherheitsmethodik, die zuerst erkennt, was ein System tats\xe4chlich tut, und dann die kontextspezifische Sicherheitsarbeit steuert, bestimmt von standardm\xe4\xdfig sicheren Prinzipien und in verst\xe4ndlicher Sprache formuliert."]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"SDH wird durch eine Reihe verbindlicher Prinzipien definiert. Jedes ist eine Regel, und jedes gibt dem Nutzer eine bestimmte Garantie."}),"\n",(0,t.jsxs)(n.table,{children:[(0,t.jsx)(n.thead,{children:(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.th,{children:"Prinzip"}),(0,t.jsx)(n.th,{children:"Die Regel"}),(0,t.jsx)(n.th,{children:"Was es dem Nutzer garantiert"})]})}),(0,t.jsxs)(n.tbody,{children:[(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Standardm\xe4\xdfig sicher, in verst\xe4ndlicher Sprache, f\xfcr alle gleicherma\xdfen"}),(0,t.jsx)(n.td,{children:"Jeder Standardwert, jede Meldung und jede Korrektur ist von Haus aus sicher und f\xfcr jeden Leser verst\xe4ndlich, ob Entwickler oder nicht. Keine Nutzergruppe wird bevorzugt."}),(0,t.jsx)(n.td,{children:"Ein Einsteiger erh\xe4lt eine sichere Grundlage, ohne danach zu fragen, und versteht das Ergebnis in seinen eigenen Worten."})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Kontextbezogen statt generisch"}),(0,t.jsx)(n.td,{children:"Jede Phase geht vom Kontext aus, den detect erkannt hat, und arbeitet mit dem, was das System tats\xe4chlich tut."}),(0,t.jsx)(n.td,{children:"Die Empfehlungen passen zum Projekt, nicht zu einer Checkliste. Das Sicherheitswissen steckt in der Spezifikation und ihren bei Bedarf geladenen Spezialisierungen und erweitert, was der Nutzer mitbringt."})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Flexibel statt starr"}),(0,t.jsx)(n.td,{children:"Prinzipien, Anforderungen und Empfehlungen sind Ausgangspunkte. Der Nutzer kann alles umformulieren, streichen, erg\xe4nzen oder eingrenzen."}),(0,t.jsx)(n.td,{children:"Die Methodik passt sich dem Projekt und dem Nutzer an und ist nie strenger, als der Nutzer es will. Flexibilit\xe4t schw\xe4cht nie die standardm\xe4\xdfig sichere Grundlage."})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Abgleichen statt nur anh\xe4ngen"}),(0,t.jsx)(n.td,{children:"Artefakte sind lebendige Dokumente, keine Logs. Jeder Lauf pr\xfcft jeden Eintrag neu: behalten, was noch gilt, umschreiben, was sich ge\xe4ndert hat, entfernen, was nicht mehr zutrifft."}),(0,t.jsx)(n.td,{children:"Die Aufzeichnungen spiegeln immer die Gegenwart wider und verkommen so nie zu einem veralteten Backlog."})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Ausschlie\xdflich defensiv"}),(0,t.jsx)(n.td,{children:"SDH auditiert, h\xe4rtet und verifiziert. Es erzeugt nie offensive Werkzeuge, Exploits f\xfcr b\xf6swillige Zwecke oder Techniken zur Umgehung von Erkennung, um Schaden anzurichten."}),(0,t.jsx)(n.td,{children:"Die Methodik l\xe4sst sich nicht als Waffe einsetzen. Dual-Use-Inhalte erscheinen nur in einem klar defensiven Rahmen."})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Spec-first, agentengesteuert, auf Sicherheit ausgerichtet"}),(0,t.jsx)(n.td,{children:"Der Workflow besteht aus Vorlagen, Befehlen, \xfcbergeordneten Sicherheitsprinzipien und einem Agenten, der die Phasen ausf\xfchrt."}),(0,t.jsx)(n.td,{children:"Eine bew\xe4hrte Entwicklungsstruktur, so umgewidmet, dass der Agent die eigentliche Sicherheitsarbeit leistet."})]})]})]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Tabelle 1."})," Die Gestaltungsprinzipien von SDH und die Garantie, die jedes dem Nutzer gibt."]}),"\n",(0,t.jsxs)(n.p,{children:["Diese Prinzipien sind keine Zierde. Sie sind die Vorgaben, die jede der folgenden Phasen einhalten muss, und die Diskussion in ",(0,t.jsx)(n.code,{children:"\xa7XV"})," greift sie wieder auf, um die Grenzen der Methodik abzustecken."]}),"\n",(0,t.jsx)(n.p,{children:"Der Rest des Dokuments entwickelt neun benannte S\xe4ulen. Sie sind die Teile, die ein Leser im Kopf behalten k\xf6nnen sollte, und die Teile, die ein anderes Team neu umsetzen w\xfcrde, um zu behaupten, es betreibe SDH."}),"\n",(0,t.jsxs)(n.table,{children:[(0,t.jsx)(n.thead,{children:(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.th,{children:"S\xe4ule"}),(0,t.jsx)(n.th,{children:"Was sie leistet"}),(0,t.jsx)(n.th,{children:"Abschnitt"})]})}),(0,t.jsxs)(n.tbody,{children:[(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Die kontextbezogene Umkehrung"}),(0,t.jsx)(n.td,{children:"Das Sicherheitswissen steckt in der Spezifikation und ihren bei Bedarf geladenen Spezialisierungen, sodass Einsteiger und Experte einen Workflow teilen."}),(0,t.jsxs)(n.td,{children:[(0,t.jsx)(n.code,{children:"\xa7I"}),", ",(0,t.jsx)(n.code,{children:"\xa7VI"})]})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Der defensive Lebenszyklus in f\xfcnf Phasen"}),(0,t.jsx)(n.td,{children:"Aufgabentrennung: Richtlinie, Erkennung, Triage, Behebung, Verifizierung, jede mit genau einer Aufgabe."}),(0,t.jsx)(n.td,{children:(0,t.jsx)(n.code,{children:"\xa7IV"})})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Abschlie\xdfbarkeit"}),(0,t.jsx)(n.td,{children:"Ein Befund hat einen Endzustand statt einer Endlosschleife. Abgeschlossene Arbeit wird ausgetragen."}),(0,t.jsx)(n.td,{children:(0,t.jsx)(n.code,{children:"\xa7V"})})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Die Dualit\xe4t als Erweiterung des Entwicklerwissens"}),(0,t.jsx)(n.td,{children:"Ein Workflow, der den Einsteiger sch\xfctzt und den Experten verst\xe4rkt, ohne einen von beiden zu ersetzen."}),(0,t.jsx)(n.td,{children:(0,t.jsx)(n.code,{children:"\xa7VI"})})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Prompt bei Bedarf, nicht aufrufbares Wissen"}),(0,t.jsx)(n.td,{children:"Relevantes Sicherheitswissen wird f\xfcr das geladen, was das Projekt ist, nie standardm\xe4\xdfig."}),(0,t.jsx)(n.td,{children:(0,t.jsx)(n.code,{children:"\xa7VII"})})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Zustandsunabh\xe4ngigkeit und nicht vorschreibende Anpassungsf\xe4higkeit"}),(0,t.jsx)(n.td,{children:"Passt in jeden Entwicklungsstand und jeden Stack und richtet sich nach dem Szenario, statt einen Umfang vorzugeben."}),(0,t.jsx)(n.td,{children:(0,t.jsx)(n.code,{children:"\xa7VIII"})})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Der pr\xe4ventive Modus"}),(0,t.jsx)(n.td,{children:"Dieselbe Verteidigung l\xe4uft mit, w\xe4hrend neue Arbeit entsteht, sodass der Code von Anfang an standardm\xe4\xdfig sicher ist."}),(0,t.jsx)(n.td,{children:(0,t.jsx)(n.code,{children:"\xa7IX"})})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Nachverfolgung mit Identit\xe4t \xfcber den Namen"}),(0,t.jsx)(n.td,{children:"Ein Befund bleibt \xfcber alle Phasen hinweg ein Eintrag, und eine Umbenennung unterbricht die Verkn\xfcpfung nur an einer Stelle."}),(0,t.jsx)(n.td,{children:(0,t.jsx)(n.code,{children:"\xa7XI"})})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Der agentenunabh\xe4ngige Tr\xe4ger"}),(0,t.jsx)(n.td,{children:"Der Sicherheitskern wird einmal geschrieben und h\xe4ngt von keinem Agenten und keinem Stack ab."}),(0,t.jsx)(n.td,{children:(0,t.jsx)(n.code,{children:"\xa7XII"})})]})]})]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Tabelle 2."})," Die neun benannten S\xe4ulen von SDH und wo jede ausgef\xfchrt wird."]}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"iv-der-blue-team-workflow-in-5-phasen",children:"IV. Der Blue-Team-Workflow in 5 Phasen"}),"\n",(0,t.jsx)(n.p,{children:"SDH gliedert die Arbeit in einen defensiven Lebenszyklus aus f\xfcnf Phasen (Abbildung 1). Jede Phase ist auf Verteidigung ausgerichtet, jede baut auf der vorherigen auf, und die Phasen folgen der echten Arbeit eines Blue Teams: Richtlinie festlegen, erkennen, triagieren, beheben, verifizieren."}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    charter["1 \xb7 charter (Richtlinie)<br/>liest: das Projekt und, falls vorhanden, die Beschreibung des Nutzers<br/>schreibt: die Sicherheitsprinzipien<br/>jedes Prinzip nennt in verst\xe4ndlicher Sprache das Risiko, das es verhindert"]\n    detect["2 \xb7 detect (Erkennung)<br/>liest: den Code des Nutzers<br/>schreibt: die Bestandsaufnahme<br/>Erkennen, nicht erfinden: nur festhalten, was der Code belegt"]\n    plan["3 \xb7 plan (Triage)<br/>liest: die Bestandsaufnahme, nie den Code<br/>schreibt: den Abwehrplan<br/>jede Korrektur verweist auf etwas, das detect tats\xe4chlich erfasst hat"]\n    harden["4 \xb7 harden (Behebung)<br/>liest: den Abwehrplan und den Code, den er betrifft<br/>schreibt: den Code und das H\xe4rtungsprotokoll<br/>die einzige Phase, die Code \xe4ndert, eine Korrektur nach der anderen, die kleinste \xc4nderung, die greift"]\n    verify["5 \xb7 verify (Verifizierung)<br/>liest: den Code und das H\xe4rtungsprotokoll<br/>schreibt: jedes offene Urteil ins H\xe4rtungsprotokoll<br/>die Gegen\xfcberstellung von Code und Protokoll, statisch, nie abgeschw\xe4cht"]\n    charter --\x3e detect --\x3e plan --\x3e harden --\x3e verify\n    verify -.->|"nicht bestanden: wieder offene Arbeit f\xfcr harden,<br/>erneut umgesetzt anhand der festgehaltenen Begr\xfcndung"| harden\n    verify -.->|"Abschluss: was als geschlossen nachgewiesen ist,<br/>wird aus der gesamten Kette ausgetragen,<br/>eine Zeile in der Historie"| detect\n'})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Abbildung 1."})," Der Workflow in f\xfcnf Phasen: was jede Phase liest, was sie schreibt und ihre tragende Invariante. Verify steuert beide R\xfcckwege: Eine nicht bestandene Schutzma\xdfnahme \xf6ffnet harden erneut, und ein als geschlossen nachgewiesener Befund wird aus der Kette ausgetragen, mit einer Zeile in der Historie."]}),"\n",(0,t.jsx)(n.p,{children:"Die Aufgabentrennung ist der Beitrag. Weil jede Phase genau eine Aufgabe hat, bleibt ein Fehler auf eine Stelle beschr\xe4nkt, und der Leser kann sich auf das verlassen, was jedes Artefakt aussagt."}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Kernaussage"})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Applied hei\xdft nicht verifiziert:"}),' Harden h\xe4lt fest, dass eine Korrektur umgesetzt wurde. Verify pr\xfcft das nach und stellt daf\xfcr den Code diesem Protokoll gegen\xfcber, und das Urteil wird nie abgeschw\xe4cht, damit es zum Protokoll passt. Eine Schutzma\xdfnahme kann im Code vorhanden sein und das Risiko trotzdem erreichbar lassen, und dann lautet das ehrliche Urteil "Risk not closed".']}),"\n"]}),"\n",(0,t.jsx)(n.h3,{id:"charter-richtlinie",children:"charter (Richtlinie)"}),"\n",(0,t.jsxs)(n.p,{children:["Die Phase charter legt die Sicherheitsprinzipien des Projekts fest, die Regeln, die jede sp\xe4tere Phase einhalten muss. Sie ist die \xfcbergeordnete Ebene, eine Art Pr\xfcfung zur Kompilierzeit f\xfcr das Sicherheitsniveau des Projekts. Jedes Prinzip hat einen klaren Namen, eine unverhandelbare Regel, die sich am Code \xfcberpr\xfcfen l\xe4sst, und eine Zeile ",(0,t.jsx)(n.code,{children:"Why:"}),", die das Risiko nennt, das es verhindert, nicht nur die Korrektur. Die Phase liest immer das Projekt selbst (seine Manifeste, seine Struktur und seine Abh\xe4ngigkeiten), und eine Beschreibung des Nutzers gibt, falls vorhanden, eine Richtung vor, die das Lesen dann \xfcber das Genannte hinaus erweitert. Ohne Beschreibung ist das Projekt die einzige Quelle. Beides erg\xe4nzt sich, statt zu konkurrieren, und die Sicherheitsprinzipien halten die Richtlinie fest, an die sich das Projekt halten soll, nicht den Zustand seines Codes. Auch wer nicht entwickelt, sollte sie lesen und sowohl die Regel als auch das Risiko verstehen k\xf6nnen."]}),"\n",(0,t.jsx)(n.h3,{id:"detect-erkennung",children:"detect (Erkennung)"}),"\n",(0,t.jsxs)(n.p,{children:['Detect liest den Code und erfasst, was das System tats\xe4chlich tut und was dabei sicherheitsrelevant ist. Die leitende Anweisung lautet "Erkennen, nicht erfinden": nur festhalten, was der Code belegt, mit den Belegen, die sp\xe4tere Phasen brauchen. Detect ist neutral. Die Phase zwingt ihre Befunde nicht in die Sicherheitsprinzipien, denn Risiken an deren Regeln zu messen, ist Aufgabe der Phase plan. Jeder Befund besteht aus drei Teilen: was er ist (eine Beschreibung in verst\xe4ndlicher Sprache), warum er wichtig ist (das Risiko, nicht nur die Tatsache) und der Beleg (die Funktion oder Route, in der er steckt). Der Beleg enth\xe4lt keinen Dateipfad. Der Pfad steht nur in der Tracking-Map (',(0,t.jsx)(n.code,{children:"\xa7XI"}),"), sodass der Text nie einen Pfad enth\xe4lt, der veralten kann."]}),"\n",(0,t.jsx)(n.h3,{id:"plan-triage",children:"plan (Triage)"}),"\n",(0,t.jsx)(n.p,{children:"Plan macht aus jedem Befund eine Korrektur, benannt nach ihrer Risikoklasse (mit Verweis auf die etablierten Referenzen CWE und OWASP, wo diese sie begr\xfcnden) und an das Sicherheitsprinzip gebunden, das die Korrektur wahrt. Die Priorit\xe4t (kritisch, hoch, mittel, niedrig) ist keine freie Wahl: plan bewertet jeden Befund nach CVSS v4.0 mit Base- und Environmental-Metriken, sodass die Stufe den Score in einfachen Worten ausdr\xfcckt, begr\xfcndet mit einer verst\xe4ndlichen Zeile zu Exposition und Tragweite, und zwei L\xe4ufe ergeben dieselbe Reihenfolge. Der Vektor ist der pr\xe4zise Anker f\xfcr Experten, die Stufe mit ihrer Begr\xfcndung dieselbe Bewertung in einer Form, der jeder folgen kann. Plan arbeitet nur mit der Bestandsaufnahme von detect und liest nie den Code. Das ist eine bewusste Vorgabe, keine Schw\xe4che: Sie zwingt jede Korrektur, auf etwas zu verweisen, das detect tats\xe4chlich erkannt hat. Wurde ein Bereich nie erfasst, h\xe4lt plan an und schickt den Nutzer zur\xfcck zu detect, statt zu raten."}),"\n",(0,t.jsx)(n.h3,{id:"harden-behebung",children:"harden (Behebung)"}),"\n",(0,t.jsx)(n.p,{children:'Harden ist die einzige Phase, die Code \xe4ndert, deshalb geht sie mit Vorsicht vor. Ob eine \xc4nderung die Zustimmung des Nutzers braucht, entscheiden der Agent und der Berechtigungsmodus, in dem er l\xe4uft, daher f\xfcgt harden keinen eigenen Best\xe4tigungsschritt hinzu. Die Phase setzt eine Korrektur nach der anderen um, zuerst die Abh\xe4ngigkeiten, dann die h\xf6chste Priorit\xe4t, damit jede \xc4nderung klein, \xfcberpr\xfcfbar und leicht r\xfcckg\xe4ngig zu machen bleibt. Sie schw\xe4cht nie eine bestehende Schutzma\xdfnahme ab, damit eine neue Korrektur passt, und sie verletzt nie eines der Sicherheitsprinzipien. W\xfcrde eine Korrektur einem Prinzip widersprechen, h\xe4lt harden an und zeigt den Konflikt auf, statt die Korrektur umzusetzen. Jeder Block wird als Applied, Partial oder Blocked festgehalten. "Applied hei\xdft noch nicht verifiziert", und darum k\xfcmmert sich die n\xe4chste Phase.'}),"\n",(0,t.jsx)(n.h3,{id:"verify-verifizierung",children:"verify (Verifizierung)"}),"\n",(0,t.jsx)(n.p,{children:'Verify liest den Code und stellt ihn dem gegen\xfcber, was harden festgehalten hat, um jede umgesetzte Schutzma\xdfnahme zu pr\xfcfen. Die Verifizierung ist genau diese Gegen\xfcberstellung, Code gegen Protokoll, und sie ist statisch: Sie best\xe4tigt, dass eine Schutzma\xdfnahme im Code vorhanden und korrekt ist, nicht dass sie auf einem laufenden System einem Angriff standh\xe4lt. Diese Pr\xfcfung zur Laufzeit, also die Art, die echte oder simulierte Angriffe gegen das laufende System ausf\xfchrt, liegt bewusst au\xdferhalb des Umfangs. Verify liefert eines von drei Urteilen: Risk closed, Risk not closed oder Cannot tell from the code. Die Phase erzeugt kein eigenes Artefakt: harden und verify teilen sich das H\xe4rtungsprotokoll, wobei harden verantwortet, was getan wurde, und verify das Urteil samt Begr\xfcndung, und keine der beiden schreibt je in die Felder der anderen. Eine nicht bestandene Schutzma\xdfnahme ist wieder offene Arbeit f\xfcr harden, deren n\xe4chster Lauf das Urteil \xfcber die eigene Lesart des Codes stellt und die Korrektur genau an der L\xfccke, die die Begr\xfcndung benennt, erneut umsetzt. Verify traut dem Code mehr als dem Protokoll, denn ein Protokoll kann mehr behaupten, als der Code leistet. Auf den Code des Nutzers greift die Phase nur lesend zu, und sie schw\xe4cht ein Urteil nie ab, damit es zum Protokoll passt. Eine Schutzma\xdfnahme kann vorhanden sein und das Risiko auf anderem Weg trotzdem erreichbar lassen, und dann lautet das ehrliche Urteil "Risk not closed". Bemerkt verify beim Lesen ein Sicherheitsproblem, das die Bestandsaufnahme von detect nie abgedeckt hat, erfindet sie daf\xfcr kein Urteil, denn das Erkennen ist Aufgabe von detect: Sie meldet das Problem und schickt den Nutzer zur\xfcck zu detect, damit der Befund \xfcber denselben Workflow hereinkommt, statt ihn zu umgehen.'}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Durchgehendes Beispiel: Datei-Uploads."})," Ein einzelner Befund zeigt das R\xfcckgrat des Workflows von Anfang bis Ende."]}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"detect"})," findet ihn: Das System nimmt Dateien von Nutzern an, und der Upload-Handler vertraut dem MIME-Typ, den der Client schickt, ohne den echten Typ der Datei zu pr\xfcfen. ",(0,t.jsx)(n.em,{children:"Warum das wichtig ist:"})," Eine als Bild getarnte Datei kann Schadcode verbergen."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"plan"})," legt die Korrektur fest, Priorit\xe4t ",(0,t.jsx)(n.strong,{children:"kritisch"}),', zur Wahrung des Prinzips "Jede Eingabe gilt als nicht vertrauensw\xfcrdig, bis sie validiert ist": den echten Typ und die Gr\xf6\xdfe der Datei pr\xfcfen, sie beim Speichern umbenennen und Uploads dort ablegen, wo sie nicht als Code ausgef\xfchrt werden k\xf6nnen.']}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"harden"})," setzt sie um, Status ",(0,t.jsx)(n.strong,{children:"Applied"}),": Der Handler erkennt den echten Typ jetzt am Inhalt, erzwingt ein Gr\xf6\xdfenlimit, lehnt alles Unerwartete ab, benennt beim Speichern um und legt die Dateien dort ab, wo kein Code ausgef\xfchrt werden kann."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"verify"})," liest den Handler, stellt ihn dem Protokoll gegen\xfcber und liefert ",(0,t.jsx)(n.strong,{children:"Risk closed"}),": Der Code tut genau das, was das Protokoll behauptet."]}),"\n"]}),"\n",(0,t.jsxs)(n.p,{children:["Derselbe Befundname zieht sich durch die Bestandsaufnahme von detect, den Abwehrplan und das H\xe4rtungsprotokoll, und verify arbeitet unter demselben Namen mit diesem Protokoll: Ein offenes Urteil wird in den Block des Befunds geschrieben, und ein als geschlossen nachgewiesener Befund wird ausgetragen (",(0,t.jsx)(n.code,{children:"\xa7V"}),"). Dieser gemeinsame Name ist seine Identit\xe4t (",(0,t.jsx)(n.code,{children:"\xa7XI"}),")."]}),"\n"]}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"v-abschlie\xdfbarkeit-ein-befund-hat-einen-endzustand",children:"V. Abschlie\xdfbarkeit: Ein Befund hat einen Endzustand"}),"\n",(0,t.jsxs)(n.p,{children:["Die meisten Sicherheitswerkzeuge hinterlassen beim Nutzer einen Backlog, der nur w\xe4chst. SDH vertritt eine andere Position: ",(0,t.jsx)(n.strong,{children:"Ein Befund ist abschlie\xdfbar, er hat also einen Endzustand, statt in einem endlosen Backlog zu leben"})," (Abbildung 2). Das folgt direkt aus dem Prinzip des Abgleichs."]}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Definition"})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Abschlie\xdfbarkeit:"})," Ein als geschlossen verifiziertes Risiko wird aus dem gesamten Workflow ausgetragen, sodass dieser Befund in den Ruhezustand \xfcbergeht und erst wieder ge\xf6ffnet wird, wenn sich der Code \xe4ndert. Ein Befund hat einen Endzustand, auch wenn das Sicherheitsprogramm selbst fortlaufend bleibt."]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Die Artefakte von SDH sind lebendige Dokumente, keine Logs. Bei jedem erneuten Lauf gleicht eine Phase jeden vorhandenen Eintrag mit dem aktuellen Stand ab und tut eines von drei Dingen: Sie beh\xe4lt, was noch gilt, schreibt um, was sich ge\xe4ndert hat, oder entfernt, was nicht mehr zutrifft. Ein Befund, den der Code inzwischen als behoben ausweist, wird einfach entfernt. Der Arbeitsstand spiegelt die Gegenwart wider, nicht die Vergangenheit."}),"\n",(0,t.jsx)(n.p,{children:"Der Abschluss ist derselbe Abgleich, an seinem Ende angekommen. Best\xe4tigt verify, dass ein Risiko geschlossen ist, tr\xe4gt sie den Befund aus dem gesamten Workflow aus: aus der Bestandsaufnahme von detect, dem Abwehrplan, dem H\xe4rtungsprotokoll und der Tracking-Map. Deshalb ist verify die eine Phase, die in die Artefakte der anderen Phasen schreibt: Sie ist die Phase, die den Kreis schlie\xdft. Wenn der Befund die Kette verl\xe4sst, verdichtet ihn das Austragen zu einem kurzen Eintrag in einer Historie, die au\xdferhalb der Arbeitskette liegt und nie erneut verarbeitet wird. Das ist die Grenze zwischen Verschwinden und Abschlie\xdfen: Ein Befund, den der Abgleich entfernt hat, weil er nicht mehr zutraf, hinterl\xe4sst nichts, w\xe4hrend sich ein als geschlossen nachgewiesener Befund seine Zeile in der Historie verdient. Ein ausgetragener Befund fehlt danach in jedem Arbeitsartefakt, und dieses Fehlen ist erwartet, keine unterbrochene Kette."}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-mermaid",children:"stateDiagram-v2\n    direction TB\n    [*] --\x3e OPEN: detect erkennt\n    OPEN --\x3e Plan: plan\n    Plan --\x3e Harden: harden\n    Harden --\x3e Verify: verify\n    Verify --\x3e StoodDown: Risk closed\n    StoodDown --\x3e SETTLED\n    SETTLED --\x3e OPEN: Code\xe4nderungen \xf6ffnen einen Befund erneut\n    Plan: plan\n    Harden: harden\n    Verify: verify\n    StoodDown: STOOD DOWN \xb7 eine Zeile in der Historie\n"})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Abbildung 2."})," Der Zustandsautomat der Abschlie\xdfbarkeit. Ein Befund durchl\xe4uft OPEN \u2192 STOOD DOWN \u2192 SETTLED und wird erst wieder ge\xf6ffnet, wenn sich der Code \xe4ndert."]}),"\n",(0,t.jsx)(n.p,{children:"Ist alles im Umfang ausgetragen, ist der Zyklus im Ruhezustand, und dieser Ruhezustand hat eine konkrete Form: Ein Artefakt, dessen letzter Befund abgeschlossen wurde, wird ganz entfernt, sodass eine vollst\xe4ndig abgeschlossene Kette nur die Sicherheitsprinzipien und die Historie \xfcbrig l\xe4sst, die Richtlinie und den Nachweis. Der Zyklus wird erst wieder ge\xf6ffnet, wenn sich der Code \xe4ndert. Die Methodik gibt jedem Befund ein klares Ende, und genau das kann ein endloser Backlog nicht."}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"vi-die-dualit\xe4t-als-erweiterung-des-entwicklerwissens",children:"VI. Die Dualit\xe4t als Erweiterung des Entwicklerwissens"}),"\n",(0,t.jsxs)(n.p,{children:["SDH ersetzt keine Menschen und keine spezialisierten Blue-Team-Werkzeuge. Es ",(0,t.jsx)(n.strong,{children:"erweitert das Wissen der Entwickler selbst"}),". Je mehr ein Entwickler von Sicherheit versteht, desto pr\xe4ziser kann er den Workflow steuern und desto mehr Autonomie hat er. Ein Entwickler, der wenig davon versteht, erh\xe4lt trotzdem ein sicheres Ergebnis, weil der automatische Modus ihn absichert."]}),"\n",(0,t.jsxs)(n.p,{children:["Die Umkehrung aus ",(0,t.jsx)(n.code,{children:"\xa7I"}),", nach der das Sicherheitswissen in der Spezifikation steckt, wirkt in beide Richtungen. F\xfcr den Einsteiger ist sie Schutz: Er muss nicht wissen, wonach er fragen soll, weil die Spezifikation Vorschl\xe4ge macht. F\xfcr den Experten ist sie Verst\xe4rkung: Dieselbe Spezifikation erlaubt ihm, den Workflow pr\xe4zise auszurichten, statt gegen eine starre Checkliste anzuarbeiten."]}),"\n",(0,t.jsx)(n.p,{children:"Jede Phase tr\xe4gt diese Dualit\xe4t in ihrer eigenen Arbeitsweise (Abbildung 3). Ohne Eingabe gestartet, arbeitet sie im Namen des Nutzers im gesamten Umfang. Mit einer Vorgabe beschr\xe4nkt sich dieselbe Phase genau auf das, worauf der Nutzer sie richtet."}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    inversion["eine Umkehrung, zwei Richtungen:<br/>das Sicherheitswissen steckt in der Spezifikation"]\n    inversion --\x3e auto["automatischer Modus (ohne Eingabe)<br/>die Phase schl\xe4gt vor und handelt<br/>im gesamten Umfang"]\n    inversion --\x3e directed["gezielter Modus (mit Eingabe)<br/>die Phase beschr\xe4nkt sich genau<br/>auf das, worauf der Nutzer sie richtet"]\n    auto --\x3e novice["der Einsteiger, gesch\xfctzt:<br/>ein sicheres Ergebnis, ohne<br/>zu wissen, wonach er fragen soll"]\n    directed --\x3e expert["der Experte, verst\xe4rkt:<br/>der Workflow pr\xe4zise ausgerichtet,<br/>keine starre Checkliste"]\n    novice -.-> phases["dieselben f\xfcnf Phasen dienen beiden:<br/>charter \xb7 detect \xb7 plan \xb7 harden \xb7 verify"]\n    expert -.-> phases\n'})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Abbildung 3."})," Die Dualit\xe4t als Erweiterung des Entwicklerwissens. Eine Umkehrung dient zwei Zielgruppen: Der automatische Modus sch\xfctzt den Einsteiger, und der gezielte Modus verst\xe4rkt den Experten, mit denselben f\xfcnf Phasen."]}),"\n",(0,t.jsxs)(n.p,{children:["Die bei Bedarf geladenen Spezialisierungen (",(0,t.jsx)(n.code,{children:"\xa7VII"}),') machen die Dualit\xe4t in ihrem eigenen Text ausdr\xfccklich. Jede sagt dem Agenten, dass ihr Wissen "dein Urteilsverm\xf6gen erweitert" und dass er \xfcber das hinaus weiterdenken soll, was die Spezialisierung liefert. Das Wissen ist eine Untergrenze, keine Obergrenze. Genau das dient beiden Zielgruppen in der Balance, die das Dokument anstrebt: Die Entwickler-Community erh\xe4lt ein substanzielles Werkzeug, und wer im Blue Team arbeitet, erh\xe4lt einen strukturierten Tr\xe4ger, der nicht vorgibt, ihm die Arbeit abzunehmen.']}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"vii-nicht-aufrufbare-spezialisierungen-und-prompt-bei-bedarf",children:"VII. Nicht aufrufbare Spezialisierungen und Prompt bei Bedarf"}),"\n",(0,t.jsxs)(n.p,{children:["Dies ist das neuartigste Muster der Methodik. SDH bringt fokussiertes Sicherheitswissen als Spezialisierungen mit, die ",(0,t.jsx)(n.strong,{children:"nur bei Bedarf"})," laden, und der Agent selbst entscheidet, welche er l\xe4dt, indem er sie mit dem Kontext des Projekts abgleicht. Wir nennen das ",(0,t.jsx)(n.strong,{children:"Prompt bei Bedarf"}),": eine M\xf6glichkeit f\xfcr den Agenten, anhand des Umfangs des Projekts, in dem er sich befindet, zu w\xe4hlen, welches Wissen er aktiviert, statt jede Pr\xfcfung standardm\xe4\xdfig auszuf\xfchren. Die Spezialisierungen entwickeln sich weiter, und jede von ihnen kann sich jederzeit \xe4ndern oder ersetzt werden. Der Beitrag ist das Muster, nicht die Spezialisierungen selbst."]}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Definition"})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Prompt bei Bedarf:"})," Der Agent w\xe4hlt aus, welches Sicherheitswissen er aktiviert, indem er es mit dem Umfang des Projekts vor ihm abgleicht, sodass das relevante Wissen f\xfcr das herangezogen wird, was das Projekt tats\xe4chlich ist, statt jede Pr\xfcfung standardm\xe4\xdfig auszuf\xfchren."]}),"\n"]}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Definition"})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Nicht aufrufbare Spezialisierung:"})," Eine fokussierte, sprachunabh\xe4ngige Einheit von Sicherheitswissen f\xfcr einen Kontext, etwa Datei-Uploads oder Code, der im Browser l\xe4uft. Sie auditiert und erkl\xe4rt, schreibt nie Code um und erzeugt nie eine Angriffseingabe. Sie ist kein Befehl: Sie l\xe4dt, wenn der Kontext, den sie abdeckt, im Umfang liegt, oder wenn ein Prompt sie beim Namen anfordert."]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Jede Spezialisierung benennt die sichereren Formen f\xfcr die Risiken, die sie abdeckt, und sagt dem Agenten, wie er in jeder Phase, die sie nutzt, mit einem Befund umgeht: wie er ihn bei der Erkennung beurteilt, wie er die Korrektur bei der Behebung sicher umsetzt und wie er sie bei der Verifizierung nachweist."}),"\n",(0,t.jsxs)(n.p,{children:["Das pr\xe4gende Merkmal ist, dass eine Spezialisierung ",(0,t.jsx)(n.strong,{children:"nicht eigenst\xe4ndig aufrufbar"})," ist: Sie ist kein Befehl, und innerhalb des Workflows l\xe4dt sie nur ein Treffer. Die Erkennungsphase listet den Katalog einmal auf, gleicht den Kontext des Projekts mit dem ab, was jeder Eintrag abdeckt, und l\xe4dt nur die Spezialisierungen, deren Kontext im Umfang vorhanden ist. Die sp\xe4teren Phasen verwenden diese Trefferliste wieder, statt erneut aufzulisten, sodass ein einziger Abgleich der gesamten Kette dient, und der pr\xe4ventive Modus (",(0,t.jsx)(n.code,{children:"\xa7IX"}),") f\xfchrt denselben Abgleich mit der Arbeit durch, die gleich entstehen soll. Eine Spezialisierung, deren Kontext fehlt, wird \xfcbersprungen, und das \xdcberspringen wird genauso begr\xfcndet wie das Laden: Jeder Eintrag im Katalog erh\xe4lt ein ausdr\xfcckliches Urteil, angewendet oder \xfcbersprungen, mit der aus dem Code abgelesenen Begr\xfcndung, sodass ein vages Gef\xfchl von Irrelevanz nie an die Stelle tats\xe4chlichen Fehlens tritt. Keine passende zu finden, ist ein g\xfcltiges Ergebnis."]}),"\n",(0,t.jsxs)(n.p,{children:["Der Katalog besteht aus Daten, und Wachstum bedeutet eine Wissensdatei plus eine Katalogzeile, nie einen neuen Befehl. Die integrierten Spezialisierungen sind in Kategorien gruppiert, etwa OWASP, eine Programmiersprache oder KI-Integrationen, und der Katalog, den ein Projekt nutzt, enth\xe4lt die integrierten Spezialisierungen der Kategorien, die es gew\xe4hlt hat, plus seine eigenen Spezialisierungen. Das Projekt h\xe4lt diese Wahl zusammen mit dem Rest seines Zustands fest, sodass ein ganzes Team mit demselben Katalog abgleicht. Das ist dasselbe kontextbezogene Prinzip wie bei den Phasen, angewandt auf Wissen: Das relevante Wissen wird f\xfcr das herangezogen, was das Projekt tats\xe4chlich ist, statt jede Pr\xfcfung standardm\xe4\xdfig auszuf\xfchren. Dieselbe Eigenschaft erlaubt es dem Nutzer, nicht nur dem Maintainer, den Katalog zu erweitern: Eine Sicherheitsquelle oder ein Thema, das der Nutzer einbringt, wird zu einer neuen Spezialisierung verdichtet, die dem Projekt geh\xf6rt, unabh\xe4ngig von den Kategorien in seinen Katalog aufgenommen wird und genau wie eine integrierte l\xe4dt, wobei sie die integrierte mit demselben Namen ersetzt. Auch das Verfassen einer Spezialisierung ist ausschlie\xdflich defensiv und folgt derselben Grenze, die die Spezialisierungen durchsetzen: Die Beschreibung eines Angriffs darf die Quelle sein, doch die daraus entstehende Spezialisierung auditiert und erkl\xe4rt, sie liefert nie einen funktionsf\xe4higen Exploit. So reicht die Umkehrung aus ",(0,t.jsx)(n.code,{children:"\xa7I"}),", die Intelligenz in der Spezifikation, bis in den Katalog selbst, den der Nutzer f\xfcr seinen eigenen Kontext vertiefen kann, ohne Code zu schreiben."]}),"\n",(0,t.jsx)(n.p,{children:"Ein kurzes Beispiel veranschaulicht Prompt bei Bedarf. Detect liest einen Ordner mit Code, der im Browser l\xe4uft. Die Phase findet diesen Kontext im Katalog, l\xe4dt die Spezialisierung, die ihn abdeckt, und meldet \xfcber die \xfcblichen Schritte von detect einen clientseitigen Befund. Die Spezialisierungen, deren Kontext in diesem Umfang fehlt, passen nicht, laden also nie, und jede wird als \xfcbersprungen festgehalten. Das Projekt hat entschieden, welches Wissen relevant war, nicht eine feste Konfiguration."}),"\n",(0,t.jsxs)(n.p,{children:["Determinismus taucht genau dort auf, wo er z\xe4hlt. Eine Spezialisierung kann ein deterministisches Pr\xfcfprogramm mitbringen, nicht nur Text: Wo eine Risikoklasse ein klares Entscheidungsverfahren hat, liefert ein kleines Programm f\xfcr eine gegebene Eingabe ein festes Urteil, zum Beispiel aus einer kurzen Menge von W\xf6rtern wie ",(0,t.jsx)(n.code,{children:"safe"}),", ",(0,t.jsx)(n.code,{children:"unsafe"})," oder ",(0,t.jsx)(n.code,{children:"invalid input"}),". Manche Risikoklassen lassen sich genau so deterministisch entscheiden, und hinter dem Entscheidungsverfahren steht eine Reihe fr\xfcherer Arbeiten ",(0,t.jsx)(n.code,{children:"[9]"}),", ",(0,t.jsx)(n.code,{children:"[10]"}),", ",(0,t.jsx)(n.code,{children:"[11]"}),". Das Pr\xfcfprogramm bewertet entweder Kandidaten, die der Agent liefert, oder durchsucht den Umfang selbst nach ihnen, und in beiden F\xe4llen liefert das Pr\xfcfprogramm das Urteil, nicht der Agent. Eine Spezialisierung, die universell genug ist, kann im Katalog als verpflichtend markiert werden und wird dann immer angewendet, wobei ihr Pr\xfcfprogramm \xfcber den gesamten Umfang l\xe4uft. Das ist der einzige Fall, in dem Wissen ohne Kontexttreffer l\xe4dt, und er ist in den Daten des Katalogs festgelegt, nie vom Agenten im Moment entschieden. Hier verankert SDH das Schlussfolgern des Agenten in etwas Wiederholbarem, ohne vorzugeben, der gesamte Workflow sei deterministisch."]}),"\n",(0,t.jsxs)(n.p,{children:["Schlie\xdflich sind die Spezialisierungen ",(0,t.jsx)(n.strong,{children:"abl\xf6sbar"}),". Weil das Wissen f\xfcr sich allein steht, kann ein Nutzer eine davon direkt in einem Prompt ausf\xfchren, der nichts mit dem vollst\xe4ndigen Workflow von SDH zu tun hat, und so die Sicherheit bei der allt\xe4glichen Entwicklung mitlaufen lassen. Eine Spezialisierung mit deterministischem Pr\xfcfprogramm kann zum Beispiel jeden Kandidaten pr\xfcfen, der w\xe4hrend der allt\xe4glichen Programmierarbeit entsteht, und nur die sicheren behalten. Diese Abl\xf6sbarkeit ist ein Grund daf\xfcr, dass sich SDH an so viele Situationen anpasst, worum es in ",(0,t.jsx)(n.code,{children:"\xa7VIII"})," geht, und ihren vollen Ausdruck findet sie im pr\xe4ventiven Modus (",(0,t.jsx)(n.code,{children:"\xa7IX"}),"), in dem dasselbe Wissen die allt\xe4gliche Entwicklung von Anfang bis Ende absichert."]}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"viii-zustandsunabh\xe4ngigkeit-und-nicht-vorschreibende-anpassungsf\xe4higkeit",children:"VIII. Zustandsunabh\xe4ngigkeit und nicht vorschreibende Anpassungsf\xe4higkeit"}),"\n",(0,t.jsx)(n.p,{children:"Zwei Eigenschaften unterscheiden SDH von starren Spezifikationsmethodiken."}),"\n",(0,t.jsx)(n.h3,{id:"zustandsunabh\xe4ngigkeit",children:"Zustandsunabh\xe4ngigkeit"}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Definition"})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Zustandsunabh\xe4ngigkeit:"})," Die Methodik h\xe4ngt nicht vom Entwicklungsstand ab. Sie passt zu einem leeren Verzeichnis, einem laufenden Projekt, einem einzelnen Pull Request oder einer gro\xdfen Legacy-Codebasis, in jedem Stack, weil sie den Ausgangspunkt erfasst, indem sie ihn liest."]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Jede Phase arbeitet gleich, ob das Projekt brandneu ist oder bereits existiert. Die Phase charter leitet Prinzipien aus dem Code ab, der gerade vorhanden ist. Detect erfasst den Code, der da ist, auch wenn es sehr wenig ist. Es gibt keinen vorausgesetzten Ausgangspunkt."}),"\n",(0,t.jsx)(n.h3,{id:"nicht-vorschreibende-anpassungsf\xe4higkeit",children:"Nicht vorschreibende Anpassungsf\xe4higkeit"}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Definition"})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Nicht vorschreibende Anpassungsf\xe4higkeit:"})," Die Methodik passt sich dem Szenario an, statt einen festen Umfang vorzugeben, dem der Nutzer folgen muss. Wei\xdf der Nutzer nicht, was er sagen soll, liest sie die Umgebung, in der sie aufgerufen wurde, erzeugt Kontext und stellt die Fragen, die bestimmen, was sie als N\xe4chstes tut."]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Der Vorschlagsmodus der Phase charter ist das deutlichste Beispiel: SDH leitet durch eine Analyse des Projekts standardm\xe4\xdfig sichere Prinzipien ab, fragt den Nutzer nur, wenn eine L\xfccke das Ergebnis tats\xe4chlich ver\xe4ndert, schreibt sie dann und stellt jedes Prinzip in verst\xe4ndlicher Sprache mit dem Risiko vor, das es verhindert. Die Sicherheitsprinzipien sind ein lebendiges Dokument, das der Nutzer durch erneutes Ausf\xfchren \xfcberarbeitet, kein Vertrag hinter einer Freigabeabfrage, und so muss der Nutzer nie wissen, wonach er fragen soll."}),"\n",(0,t.jsx)(n.p,{children:"Diese Anpassungsf\xe4higkeit zeigt sich als Gesp\xfcr f\xfcr die Form der Eingabe: Dieselbe Phase liest, was sie bekommen hat, und w\xe4hlt einen Modus (Abbildung 4). Eine Datei im Prompt, ein Befund aus der Liste, eine Sorge, ein gezielter Auftrag gegen einen bekannten Schwachpunkt oder der Wunsch nach einem vollst\xe4ndigen Brute-Force-Durchlauf: Jedes davon passt zu dem, was der Nutzer braucht, weil der Workflow von Grund auf nicht vorschreibend ist. Nichts davon schw\xe4cht die standardm\xe4\xdfig sichere Grundlage. Flexibilit\xe4t bestimmt, wie die Grundlage angewendet wird, sie senkt sie nie."}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    shape["die Phase liest die Form<br/>dessen, was sie bekommen hat"]\n    shape --\x3e none["keine Eingabe"]\n    shape --\x3e paths["ein oder mehrere Pfade"]\n    shape --\x3e concern["ein beschriebenes Anliegen"]\n    shape --\x3e finding["ein benannter Befund"]\n    shape --\x3e band["eine Priorit\xe4tsstufe"]\n    none --\x3e auto["der automatische Modus:<br/>vorschlagen oder den gesamten<br/>Umfang durchsuchen"]\n    paths --\x3e focus["nur auf diese Dateien<br/>oder Verzeichnisse konzentrieren"]\n    concern --\x3e scoped["auf dieses eine<br/>Anliegen beschr\xe4nken"]\n    finding --\x3e item["nur diesen einen<br/>nachverfolgten Eintrag bearbeiten"]\n    band --\x3e priority["nur eine Stufe bearbeiten:<br/>kritisch, hoch, mittel oder niedrig"]\n'})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Abbildung 4."})," Nicht vorschreibende Anpassungsf\xe4higkeit. Dieselbe Phase liest die Form ihrer Eingabe und w\xe4hlt einen Modus, sodass der Umfang immer beim Nutzer liegt und nie vorgegeben wird."]}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"ix-der-universelle-pr\xe4ventive-modus-dieselbe-verteidigung-w\xe4hrend-die-arbeit-entsteht",children:"IX. Der universelle pr\xe4ventive Modus: dieselbe Verteidigung, w\xe4hrend die Arbeit entsteht"}),"\n",(0,t.jsx)(n.p,{children:"SDH bringt einen erg\xe4nzenden Modus mit: allt\xe4gliche Entwicklung, bei der dieselbe Verteidigung aktiv ist, w\xe4hrend der Code geschrieben wird. Der Nutzer bittet um die Arbeit selbst, eine Anmeldeseite, einen Upload, einen Endpoint, und die Methodik sichert die Entwicklung ab, w\xe4hrend sie geschieht, sodass das Ergebnis in dem Moment standardm\xe4\xdfig sicher ist, in dem es fertig ist, statt erst nach einer sp\xe4teren H\xe4rtung."}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Definition"})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Der pr\xe4ventive Modus:"})," allt\xe4gliche Entwicklung unter der \xfcbergeordneten Ebene und dem Wissen von SDH. Die Sicherheitsprinzipien binden die Entwicklung, die Spezialisierungen, die f\xfcr das gerade Entstehende relevant sind, laden bei Bedarf, und das Ergebnis wird genau der Verteidigung gegen\xfcbergestellt, die eingesetzt wurde, bevor die Arbeit als fertig gilt."]}),"\n"]}),"\n",(0,t.jsxs)(n.p,{children:["Der Modus verwendet jedes Teil wieder, das die Phasen bereits mitbringen, nur gerichtet auf Code, den es noch nicht gibt. Die Kontexterkennung wendet sich vom Code zur Absicht: Der Agent denkt durch, was er gleich bauen wird und welche Grenzen diese Arbeit \xfcberschreitet (eine Anmeldung bedeutet Zugangsdaten, eine Sitzung und Eingaben von au\xdfen), und genau diese \xdcberlegung wird mit dem Wissenskatalog abgeglichen. Prompt bei Bedarf (",(0,t.jsx)(n.code,{children:"\xa7VII"}),") wird hier verallgemeinert: Kontext l\xe4sst sich im Plan f\xfcr Code erkennen, nicht nur in bestehendem Code. Die Sicherheitsprinzipien gelten wie immer, und eine Anfrage, die ein Prinzip verletzen w\xfcrde, wird als Konflikt gemeldet und nie gebaut. Die Verteidigung wird direkt angewendet, in dem Moment, in dem jedes Teil geschrieben wird, mit Validierung an der Grenze und dem sicheren Konstrukt gleich beim ersten Mal, sodass nie eine funktionierende, aber unsichere Version entsteht, die korrigiert werden m\xfcsste."]}),"\n",(0,t.jsx)(n.p,{children:"Der Modus endet so, wie verify beginnt. Bevor die Arbeit als fertig gilt, stellt derjenige, der sie gebaut hat, das eigene Ergebnis der eingesetzten Verteidigung gegen\xfcber: Die Schutzma\xdfnahme muss auf dem Weg des Risikos liegen, nicht daneben, sie muss vollst\xe4ndig sein, und wo eine Spezialisierung ein deterministisches Pr\xfcfprogramm mitbringt, hat dessen Urteil Vorrang vor der eigenen Lesart des Agenten. Eine L\xfccke, die hier auff\xe4llt, wird als Teil derselben Arbeit geschlossen, denn die Arbeit fertigzustellen hei\xdft, sie sicher fertigzustellen."}),"\n",(0,t.jsxs)(n.p,{children:["Was der Modus ablehnt, ist ebenso bewusst gew\xe4hlt wie das, was er tut. Er baut nur, was verlangt wurde, und auditiert nichts drumherum: Das Auditieren des Bestehenden ist Sache der Phasen. Er schreibt kein Artefakt und verfolgt keinen Befund nach, denn ein Befund ist ein in Bestehendem erkanntes Risiko, und der Zweck dieses Modus ist, dass die unsichere Version gar nicht erst entsteht. Die beiden Richtungen erg\xe4nzen sich: Die Phasen schlie\xdfen ab, was schon da ist (",(0,t.jsx)(n.code,{children:"\xa7V"}),"), und der pr\xe4ventive Modus verhindert, dass neue Arbeit es wieder \xf6ffnet. Eine Kette im Ruhezustand bleibt im Ruhezustand, nicht weil die Entwicklung stillsteht, sondern weil alles, was in dieser Zeit entsteht, von vornherein abgesichert entsteht."]}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"x-security-driven-hardening-im-vergleich-zu-spec-driven-development",children:"X. Security-Driven Hardening im Vergleich zu Spec-Driven Development"}),"\n",(0,t.jsxs)(n.p,{children:["Security-Driven Hardening (SDH) ist aus der Basis von Spec-Driven Development (SDD) hervorgegangen und hat sich dann deutlich davon entfernt. Das strukturelle Erbe ist real und anerkannt: Spec-first, agentengesteuert, ein \xfcbergeordnetes Dokument und eine Reihe von Befehlen in Phasen, die der Agent ausf\xfchrt. SDH \xfcbernimmt diese Struktur bewusst. Anders sind der Zweck, das Autorit\xe4tsmodell, der vorausgesetzte Zustand und die Endbedingung. Wir behandeln SDD als Klasse und nehmen den Bericht von Piskala ",(0,t.jsx)(n.code,{children:"[1]"})," als ma\xdfgebliche Darstellung der Methodik, Spec Kit von GitHub ",(0,t.jsx)(n.code,{children:"[2]"})," als ma\xdfgebliches Toolkit f\xfcr Agenten und OpenSpec ",(0,t.jsx)(n.code,{children:"[3]"})," als zweites Werkzeug aus derselben Familie."]}),"\n",(0,t.jsxs)(n.p,{children:["SDD stellt die herk\xf6mmliche Entwicklung auf den Kopf, indem es Spezifikationen ausf\xfchrbar macht: Die Spezifikation erzeugt direkt eine funktionierende Implementierung, statt sie nur anzuleiten ",(0,t.jsx)(n.code,{children:"[1]"}),". Seine Phasen treiben eine Entwicklung voran ",(0,t.jsx)(n.code,{children:"[2]"})," (\xfcbergeordnete Prinzipien festlegen, spezifizieren, was gebaut wird, den Tech-Stack planen, den Plan in Aufgaben zerlegen, dann implementieren). Sein \xfcbergeordnetes Dokument, eine Verfassung aus Prinzipien, ist das Fundament, an das sich der Agent durchgehend halten muss. Das ist der Kern des Unterschieds. Bei SDD flie\xdft die Autorit\xe4t von der Spezifikation in die Entwicklung, und von der Implementierung wird erwartet, dass sie ihr folgt."]}),"\n",(0,t.jsx)(n.p,{children:"SDH kehrt fast jede Achse dieses Vertrags um (Tabelle 3)."}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Kernaussage"})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Der zentrale Unterschied:"})," Bei SDD flie\xdft die Autorit\xe4t von der Spezifikation in die Entwicklung, und von der Implementierung wird erwartet, dass sie ihr folgt. SDH ist nicht vorschreibend und flie\xdft in die andere Richtung, vom erkannten Kontext des Systems nach innen, und h\xe4rtet, was bereits da ist."]}),"\n"]}),"\n",(0,t.jsxs)(n.table,{children:[(0,t.jsx)(n.thead,{children:(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.th,{children:"Achse"}),(0,t.jsx)(n.th,{children:"SDD"}),(0,t.jsx)(n.th,{children:"SDH"})]})}),(0,t.jsxs)(n.tbody,{children:[(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Ziel"}),(0,t.jsx)(n.td,{children:"Funktionen liefern. Die Spezifikation wird zu einer funktionierenden Implementierung."}),(0,t.jsx)(n.td,{children:"H\xe4rten, was existiert oder gerade entsteht. Jede Phase ist auf Verteidigung ausgerichtet."})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Autorit\xe4tsmodell"}),(0,t.jsx)(n.td,{children:"Vorschreibend. Spezifikation und Verfassung beschr\xe4nken die Entwicklung auf einen Umfang, dem sie folgen muss."}),(0,t.jsx)(n.td,{children:"Nicht vorschreibend. SDH passt sich dem Szenario an, und der Nutzer kann umformulieren, streichen oder eingrenzen."})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Zustandsannahme"}),(0,t.jsx)(n.td,{children:"Eine Vorw\xe4rtsentwicklung aus einer Spezifikation."}),(0,t.jsx)(n.td,{children:"Zustandsunabh\xe4ngig: leeres Verzeichnis, laufendes Projekt, ein einzelner PR oder Legacy."})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Endbedingung"}),(0,t.jsx)(n.td,{children:"Endet, wenn die Funktion gebaut ist."}),(0,t.jsx)(n.td,{children:"Abschlie\xdfbar. Ein Befund erreicht den Ruhezustand und wird erst wieder ge\xf6ffnet, wenn sich der Code \xe4ndert."})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"\xdcbergeordnetes Dokument"}),(0,t.jsx)(n.td,{children:"Eine Verfassung aus Prinzipien, an die sich der Agent halten muss."}),(0,t.jsxs)(n.td,{children:["Sicherheitsprinzipien, die vom Risiko her formuliert sind (jedes mit einer Zeile ",(0,t.jsx)(n.code,{children:"Why:"}),"), ausdr\xfccklich kein fester Vertrag."]})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Wie Wissen w\xe4chst"}),(0,t.jsx)(n.td,{children:"Einen Befehl hinzuf\xfcgen (oder die Phasen erweitern)."}),(0,t.jsx)(n.td,{children:"Eine nicht aufrufbare Spezialisierung hinzuf\xfcgen, die der Agent bei Bedarf l\xe4dt: eine Datei plus eine Katalogzeile, kein neuer Befehl."})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Wem es dient"}),(0,t.jsx)(n.td,{children:"Jemandem, der eine Funktion vorantreibt."}),(0,t.jsx)(n.td,{children:"Jedem Nutzer, ob Entwickler oder nicht, im selben Workflow."})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Was Code \xe4ndert"}),(0,t.jsx)(n.td,{children:"Die Implementierungsphase erzeugt das Ergebnis."}),(0,t.jsx)(n.td,{children:"Nur die Phase harden \xe4ndert Code, eine Korrektur nach der anderen."})]})]})]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Tabelle 3."})," SDD und SDH im Vergleich \xfcber acht Achsen. Geliehene Struktur, umgekehrter Vertrag."]}),"\n",(0,t.jsxs)(n.p,{children:["Um der Herkunft gerecht zu werden: SDD ist bew\xe4hrter Stand der Technik, und SDH verdankt ihm die Struktur, auf der es l\xe4uft. Die Abweichung ist keine Kritik an SDD, das ein anderes Problem (die Vorw\xe4rtsentwicklung) gut l\xf6st. SDH nimmt dieselbe bew\xe4hrte Maschinerie und richtet sie auf Verteidigung, Anpassungsf\xe4higkeit und Abschluss aus. OpenSpec ",(0,t.jsx)(n.code,{children:"[3]"}),", aufgebaut um \xc4nderungsvorschl\xe4ge, Aufgabenlisten und Spezifikationen pro \xc4nderung, best\xe4tigt das Muster: Die Familie treibt eine Entwicklung von einer Spezifikation aus voran, w\xe4hrend SDH ein System ausgehend von seinem erkannten Kontext nach innen h\xe4rtet. Selbst der pr\xe4ventive Modus von SDH (",(0,t.jsx)(n.code,{children:"\xa7IX"}),"), die einzige Stelle, an der es eine Vorw\xe4rtsentwicklung begleitet, beh\xe4lt den umgekehrten Vertrag bei: Er bestimmt, wie die Arbeit gebaut wird, und entscheidet nie, was gebaut wird."]}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"xi-technische-sorgfalt-die-disziplin-der-nachverfolgung",children:"XI. Technische Sorgfalt: die Disziplin der Nachverfolgung"}),"\n",(0,t.jsxs)(n.p,{children:["Die Disziplin, abzugleichen statt nur anzuh\xe4ngen (",(0,t.jsx)(n.code,{children:"\xa7V"}),"), braucht eine Grundlage, die Refactorings \xfcbersteht. Ein Befund muss \xfcber jede Phase hinweg, die ihn ber\xfchrt, ein Eintrag bleiben, und eine umbenannte oder verschobene Datei darf die Kette nicht unterbrechen. SDH l\xf6st das mit ",(0,t.jsx)(n.strong,{children:"Identit\xe4t \xfcber den Namen"})," und ",(0,t.jsx)(n.strong,{children:"Pfaden nur in der Nachverfolgung"}),"."]}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Definition"})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Identit\xe4t \xfcber den Namen:"})," Die Identit\xe4t eines Befunds ist sein Name, in jedem Artefakt identisch geschrieben. Der Text tr\xe4gt den Namen, nie einen Pfad. Dateipfade stehen nur in der Tracking-Map, sodass eine Umbenennung oder eine verschobene Datei die Verkn\xfcpfung an genau einer Stelle unterbricht."]}),"\n"]}),"\n",(0,t.jsxs)(n.p,{children:["Jeder Befund von detect ist ein nachverfolgter Eintrag. Seine Identit\xe4t ist sein ",(0,t.jsx)(n.strong,{children:"Name"}),", der Abschnittstitel, identisch geschrieben in der Bestandsaufnahme von detect, im Abwehrplan und im H\xe4rtungsprotokoll. Die sp\xe4teren Phasen \xfcbernehmen diesen Namen w\xf6rtlich, wenn sie an demselben Eintrag arbeiten, und verify schreibt ihr Urteil unter genau diesem Namen ins H\xe4rtungsprotokoll. Die Tracking-Map enth\xe4lt Nachverfolgung und sonst nichts, einen Eintrag pro Befund:"]}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-json",children:'{ "name": "File uploads", "paths": ["src/routes/upload.ts"] }\n'})}),"\n",(0,t.jsx)(n.p,{children:"Die Tracking-Map h\xe4lt keinen Text fest, keine Anmerkungen, keine separate Kennung und keine Phase. Die Textartefakte tragen den Wortlaut, und die Map tr\xe4gt nur Identit\xe4t und Pfade. Dateipfade sind das einzig Ver\xe4nderliche, und sie stehen nur hier. Eine Umbenennung oder eine verschobene Datei kann die Verkn\xfcpfung an genau einer Stelle unterbrechen, nie in zwei auseinanderlaufenden Kopien."}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    detect["die Bestandsaufnahme von detect"] --\x3e name\n    plan["der Abwehrplan"] --\x3e name\n    harden["das H\xe4rtungsprotokoll<br/>verify schreibt hier ihr Urteil"] --\x3e name\n    name["name = &quot;File uploads&quot;<br/>der Text tr\xe4gt den Namen, nie einen Pfad"]\n    name -.-> tracking\n    tracking["die Tracking-Map<br/>{ name: &quot;File uploads&quot;,<br/>paths: [&quot;src/routes/upload.ts&quot;] }<br/>der Pfad steht nur hier, also korrigiert eine Umbenennung nur diesen Eintrag"]\n'})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Abbildung 5."})," Das F\xf6rderband der Identit\xe4t. Ein Befundname flie\xdft durch jedes Artefakt, w\xe4hrend sein Pfad nur in der Tracking-Map steht, sodass eine Umbenennung an einer Stelle korrigiert wird."]}),"\n",(0,t.jsxs)(n.p,{children:["Zwei Vorg\xe4nge pflegen die Map im normalen Workflow, und ein dritter steht als Wartung f\xfcr sich. ",(0,t.jsx)(n.strong,{children:"Track"})," ist eine additive Registrierung: Eine Phase meldet die Befunde, die sie geschrieben hat, und die Engine erfasst die neuen und folgt bei den \xfcbrigen einem umbenannten Pfad, wobei sie jeden als neu, verschoben oder unver\xe4ndert einordnet. Track entfernt nie etwas, das die Phase nicht gemeldet hat. ",(0,t.jsx)(n.strong,{children:"Untrack"})," tr\xe4gt die Befunde aus, die verify abgeschlossen hat: In einem deterministischen Durchgang verdichtet er jeden zu seinem Eintrag in der Historie, entfernt seinen gesamten Abschnitt aus den Artefakten, l\xf6scht ein Artefakt, dessen letzter Befund weg ist, und streicht seinen Tracking-Eintrag, sodass der Agent nichts davon von Hand erledigt. Wo der deterministische Durchgang nicht sicher weiterkommt, etwa bei einem ausgetragenen Namen, der noch im Text eines anderen Befunds zitiert wird, meldet er die Stelle dem Agenten, statt eine \xc4nderung zu raten. Diese beiden rufen die Phasen w\xe4hrend ihrer Arbeit auf. ",(0,t.jsx)(n.strong,{children:"Repair"})," ist der Wartungsvorgang: Eine Phase \xfcbergibt automatisch an ihn, wenn ihr eigener Abgleich die Nachverfolgung als inkonsistent erkennt (ein festgehaltener Pfad, den es nicht mehr gibt), und ansonsten wird er bei Bedarf ausgef\xfchrt. Er richtet die gesamte Map auf einmal neu aus, liest jedes Artefakt und den aktuellen Code, korrigiert die Pfade jedes Eintrags und legt offen, was er nicht allein entscheiden kann: einen verwaisten Eintrag (einen nachverfolgten Eintrag, den kein Artefakt mehr nennt) oder einen Umbenennungskandidaten (einen Eintrag, dessen Pfade zu einem anderen gemeldeten Namen passen)."]}),"\n",(0,t.jsx)(n.p,{children:"Repair ist Wartung, keine sechste Phase. Er ber\xfchrt weder den Code des Nutzers noch die Textartefakte, nur die Nachverfolgung. Den Quellcode des Nutzers liest er aus genau einem Grund, um den neuen Pfad einer umbenannten Datei zu erfahren, und er verfasst nie Sicherheitsinhalte. Der Mensch hat das letzte Wort bei der einen Entscheidung, die die Engine nicht raten will: ob ein verschwundener Eintrag behoben oder nur umbenannt wurde. Lieber fragen als raten, denn ein f\xe4lschlich gestrichener Eintrag unterbricht die Kette."}),"\n",(0,t.jsx)(n.p,{children:"Die Methodik wendet ihre eigene Verteidigungsdisziplin auf sich selbst an. Die deterministischen Engines werden als Kommandozeilenprogramme aufgerufen, und jede Eingabe wird als eigenes Prozessargument \xfcbergeben, was sie unsch\xe4dlich h\xe4lt, sodass ein Wert mit Anf\xfchrungszeichen oder Backticks nie in den Befehl eingeschleust werden kann. Eine unbekannte Pr\xfcfung schl\xe4gt fehl, statt zu antworten, sodass eine falsch geschriebene nie als sauberes Ergebnis durchgeht. SDH nimmt seine eigene Infrastruktur nicht vom Prinzip der standardm\xe4\xdfigen Sicherheit aus."}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"xii-der-tr\xe4ger-agentenunabh\xe4ngige-architektur-als-nachweis-der-portabilit\xe4t",children:"XII. Der Tr\xe4ger: agentenunabh\xe4ngige Architektur als Nachweis der Portabilit\xe4t"}),"\n",(0,t.jsx)(n.p,{children:"Damit SDH eine Konvention sein kann, die andere \xfcbernehmen, darf es nicht an einen Agenten oder einen Stack gebunden sein, deshalb h\xe4lt sein Tr\xe4ger drei Zust\xe4ndigkeiten auseinander (Abbildung 6). Lagune belegt, dass das machbar ist."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Der Sicherheitskern"})," wird einmal geschrieben und wei\xdf nichts davon, welcher Agent ihn ausf\xfchrt: die Phasenanweisungen und die Vorlagen, die sie ausf\xfcllen, der Wissenskatalog und die deterministischen Engines. ",(0,t.jsx)(n.strong,{children:"Die Auslieferung"})," ist schlank: Ihre einzige Aufgabe ist, diesen Kern zu einem bestimmten Agenten zu bringen, in der Form und an den Ort, die der Agent erwartet, und sie enth\xe4lt keine eigene Sicherheitslogik. ",(0,t.jsx)(n.strong,{children:"Der Zustand des Projekts"})," geh\xf6rt dem Projekt: die Sicherheitsprinzipien, die Phasen-Artefakte, die Tracking-Map, die gew\xe4hlten Kategorien und die eigenen Spezialisierungen, committet und \xfcberpr\xfcfbar wie jeder andere Teil seines Codes."]}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    value["der Sicherheitskern, einmal geschrieben<br/>Phasenanweisungen \xb7 Vorlagen \xb7 Wissenskatalog \xb7 deterministische Engines<br/>wei\xdf nicht, welcher Agent ihn ausf\xfchrt"]\n    delivery["die Auslieferung<br/>bringt diesen Kern zu jedem Agenten in der Form, die er erwartet<br/>enth\xe4lt keine Sicherheitslogik"]\n    agent["der Agent<br/>f\xfchrt die Phasen aus"]\n    project["der Zustand des Projekts<br/>zusammen mit seinem Code committet<br/>Sicherheitsprinzipien \xb7 Phasen-Artefakte \xb7 Nachverfolgung \xb7 Kategorien \xb7 eigene Spezialisierungen"]\n    value --\x3e delivery --\x3e agent\n    agent --\x3e|"liest und schreibt"| project\n'})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Abbildung 6."})," Der agentenunabh\xe4ngige Tr\xe4ger. Der Sicherheitskern wird einmal geschrieben, eine schlanke Auslieferung bringt ihn zu jedem Agenten, und der Zustand bleibt beim Projekt."]}),"\n",(0,t.jsx)(n.p,{children:"Weil die Auslieferung keine Sicherheitslogik enth\xe4lt, \xe4ndert die Art, wie sie gebaut ist, nichts an SDH. Ein Tr\xe4ger kann die Auslieferung selbst bauen oder einem \xd6kosystem \xfcberlassen, das bereits Skills f\xfcr Agenten verteilt, wie es die Referenzimplementierung tut, und die Phasen, ihre Artefakte und ihre Garantien bleiben dieselben. Nichts davon ist zudem an eine Sprache oder eine Laufzeitumgebung gebunden. Die Referenzimplementierung ist zuf\xe4llig in einem bestimmten Stack geschrieben, doch die Methodik ist die Grenze zwischen diesen Zust\xe4ndigkeiten, nicht die Toolchain, die sie baut. Dasselbe Design lie\xdfe sich in einer ganz anderen Sprache neu umsetzen, ohne zu \xe4ndern, was SDH ist."}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"xiii-fallbeispiel-sdh-von-anfang-bis-ende",children:"XIII. Fallbeispiel: SDH von Anfang bis Ende"}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Fallbeispiel"})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Defensive H\xe4rtung einer Upload- und Admin-Oberfl\xe4che."}),"\n",(0,t.jsx)(n.strong,{children:"Kontext:"})," eine kleine App, die Datei-Uploads von Nutzern annimmt und sie auf einer Admin-Seite auflistet.\n",(0,t.jsx)(n.strong,{children:"Muster:"})," charter \u2192 detect (mit Wissen, das der Kontext bei Bedarf aktiviert) \u2192 plan \u2192 harden \u2192 verify, mit einem Abschluss und einem echten Fehlschlag.\n",(0,t.jsx)(n.strong,{children:"Ergebnis (F\xe4higkeit):"})," ein Risiko, das als geschlossen verifiziert und aus der Kette ausgetragen wird, und eine Schutzma\xdfnahme, die als ",(0,t.jsx)(n.em,{children:"nicht"})," geschlossen verifiziert und an harden zur\xfcckgegeben wird. Das Urteil spiegelt den Code wider, nicht das Protokoll."]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.em,{children:"Dies ist ein veranschaulichendes Beispiel f\xfcr die Mechanik der Methodik, keine im Feld gemessene Studie, und es nennt keine Kennzahlen zur Wirksamkeit."})}),"\n",(0,t.jsxs)(n.p,{children:["Ein durchgehender Ablauf zeigt die Methodik in Aktion, nicht nur ihre Teile. Wir erweitern das Datei-Upload-Beispiel aus ",(0,t.jsx)(n.code,{children:"\xa7IV"})," um eine Aktivierung von Wissen bei Bedarf und einen Abschluss, und wir nehmen einen echten Fehlschlag auf."]}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"charter"}),' schl\xe4gt das Prinzip "Jede Eingabe gilt als nicht vertrauensw\xfcrdig, bis sie validiert ist" vor, mit seinem Risiko in verst\xe4ndlicher Sprache: Ungepr\xfcfte Eingaben sind der h\xe4ufigste Weg, ein System zu kompromittieren.']}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"detect"})," durchsucht die Upload-Route und die kleine Admin-Seite, die hochgeladene Dateien auflistet. Die Phase erkennt den Upload-Befund (der Handler vertraut dem MIME-Typ des Clients). Die Admin-Seite l\xe4uft im Browser, ein Kontext, den Prompt bei Bedarf (",(0,t.jsx)(n.code,{children:"\xa7VII"}),") erkennt, also l\xe4dt detect die Spezialisierung f\xfcr diesen Kontext und meldet einen zweiten Befund: eine Stelle, an der ein Dateiname als Markup statt als Text in die Seite geschrieben wird, sodass ein manipulierter Name im Browser des Besuchers als Skript ausgef\xfchrt werden kann. Spezialisierungen, deren Kontext in diesem Umfang fehlt, laden nie, und jedes \xdcberspringen wird festgehalten, wobei das Fehlen am Code abgelesen wird."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"plan"})," gibt der Upload-Korrektur die Priorit\xe4t kritisch, gebunden an das Prinzip: den echten Typ und die Gr\xf6\xdfe der Datei pr\xfcfen, beim Speichern umbenennen, dort ablegen, wo kein Code ausgef\xfchrt werden kann. Der zweiten Korrektur gibt die Phase die Priorit\xe4t hoch: den Dateinamen als Text darstellen, nicht als Markup."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"harden"})," setzt zuerst die Upload-Korrektur um (h\xf6chste Priorit\xe4t) und h\xe4lt sie als Applied fest, danach die zweite, ebenfalls Applied."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"verify"})," liest jede Stelle und stellt Code und Protokoll gegen\xfcber. Die Upload-Schutzma\xdfnahme greift: Der Handler erkennt den echten Typ am Inhalt, erzwingt ein Gr\xf6\xdfenlimit und lehnt den Rest ab. Urteil: Risk closed. Verify tr\xe4gt den Upload-Befund aus der gesamten Kette aus, und seine verdichtete Zusammenfassung landet in der Historie."]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:'Es folgt der echte Fehlschlag. Angenommen, die zweite Korrektur von harden hat eine sichere Hilfsfunktion zur Textdarstellung hinzugef\xfcgt, aber den alten Aufruf, der Markup schreibt, auf einem anderen Codepfad weiterhin erreichbar gelassen. Verify liest die Seite, sieht die sichere Hilfsfunktion und sieht auch, dass der unsichere Pfad noch aktiv ist. Die Schutzma\xdfnahme ist vorhanden, aber das Risiko ist nicht geschlossen. Verify weigert sich, das Urteil abzuschw\xe4chen, damit es zum Protokoll passt. Die Phase liefert "Risk not closed", h\xe4lt die L\xfccke fest und verweist zur\xfcck an harden. Eine Schutzma\xdfnahme, die das Risiko nicht vollst\xe4ndig behebt, gilt nicht als bestanden.'}),"\n",(0,t.jsx)(n.p,{children:"Das ist der Charakter der Methodik in einem Beispiel: kontextbezogene Erkennung, priorisierte Korrekturen, die an Prinzipien gebunden sind, sorgf\xe4ltige Umsetzung und eine Verifizierung, die den tats\xe4chlichen Zustand des Codes meldet, unabh\xe4ngig vom Protokoll."}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"xiv-wann-sich-sdh-eignet-und-wo-seine-grenzen-liegen",children:"XIV. Wann sich SDH eignet und wo seine Grenzen liegen"}),"\n",(0,t.jsxs)(n.p,{children:["SDH ist selten so unverh\xe4ltnism\xe4\xdfig, wie es ein schwerf\xe4lliger Prozess sein kann, weil es zustandsunabh\xe4ngig und abschlie\xdfbar ist: Es l\xe4sst sich auf eine einzelne Datei und ein einzelnes Anliegen herunterskalieren und erreicht einen Ruhezustand, statt eine dauerhafte Last zu hinterlassen. Seine Grenze ist nicht die Projektgr\xf6\xdfe, sondern die ",(0,t.jsx)(n.strong,{children:"Tiefe der Absicherung"}),"."]}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-mermaid",children:'flowchart TB\n    q1{"Macht der Code etwas Sicherheitsrelevantes?<br/>(Eingaben, Authentifizierung, Daten, Secrets, externe Aufrufe)"}\n    q1 --\x3e|nein| little["Hier bringt SDH wenig."]\n    q1 --\x3e|ja| q2{"F\xfchre SDH aus. Gibt es Compliance-Vorgaben<br/>oder eine eigene Sicherheitsabteilung?"}\n    q2 --\x3e|nein| baseline["SDH ist eine belastbare Grundlage."]\n    q2 --\x3e|ja| carrier["SDH ist der strukturierte Tr\xe4ger:<br/>es unterst\xfctzt Pr\xfcfung und Audit durch Experten,<br/>es ersetzt sie nicht."]\n'})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Abbildung 7."})," Wann sich SDH eignet. Die Verzweigung fragt zuerst nach der Sicherheitsrelevanz, dann nach der Tiefe der Absicherung, nie nach der Projektgr\xf6\xdfe."]}),"\n",(0,t.jsx)(n.p,{children:"Wo SDH an seine Grenze st\xf6\xdft: Verhalten, das nur auftritt, wenn das System l\xe4uft (verify liest Code, sie f\xfchrt das System nicht aus), Risiken, die von einer Konfiguration oder einer Umgebung abh\xe4ngen, die der Agent nicht lesen kann, und Kontexte, in denen so viel auf dem Spiel steht, dass eine Pr\xfcfung durch Experten ohnehin vorgeschrieben ist. In jedem dieser F\xe4lle bringt SDH als strukturierter erster Durchgang weiterhin Nutzen, aber es ist eine Untergrenze, keine Obergrenze."}),"\n",(0,t.jsxs)(n.blockquote,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:"Kernaussage"})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Die Grenze:"})," Die Grenze von SDH ist die Tiefe der Absicherung, nicht die Projektgr\xf6\xdfe. Es kann fast \xfcberall als belastbare Grundlage dienen und unterst\xfctzt eine Pr\xfcfung durch Experten, wo viel auf dem Spiel steht, doch es ersetzt weder Tests am laufenden System noch das Urteil von Sicherheitsfachleuten."]}),"\n"]}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"xv-diskussion-einordnung-grenzen-und-was-sdh-nicht-behauptet",children:"XV. Diskussion: Einordnung, Grenzen und was SDH nicht behauptet"}),"\n",(0,t.jsx)(n.p,{children:"SDH ist pr\xe4zise, was seine Grenzen angeht."}),"\n",(0,t.jsx)(n.h3,{id:"es-erweitert-es-ersetzt-nicht",children:"Es erweitert, es ersetzt nicht"}),"\n",(0,t.jsxs)(n.p,{children:["SDH ersetzt weder Sicherheitsfachleute noch spezialisierte Blue-Team-Werkzeuge. Es erweitert das Wissen der Entwickler (",(0,t.jsx)(n.code,{children:"\xa7VI"}),"). Eine ma\xdfvolle Aussage ist die richtige: Gut angewendet ",(0,t.jsx)(n.strong,{children:"kann"})," SDH reale Risiken wirksam schlie\xdfen, besonders bei Projekten, die sonst \xfcberhaupt keine Sicherheitspr\xfcfung bek\xe4men. Es ist keine Garantie und kein Ersatz f\xfcr eine Pr\xfcfung durch Experten, wo viel auf dem Spiel steht."]}),"\n",(0,t.jsx)(n.h3,{id:"ausschlie\xdflich-defensiv-vom-aufbau-her",children:"Ausschlie\xdflich defensiv, vom Aufbau her"}),"\n",(0,t.jsx)(n.p,{children:"SDH auditiert, h\xe4rtet und verifiziert. Es erzeugt nie offensive Werkzeuge, Exploits oder Techniken zur Umgehung von Erkennung, um Schaden anzurichten. Dual-Use-Sicherheitsinhalte sind nur in einem klar defensiven, autorisierten Rahmen zul\xe4ssig. Das ist eine harte Grenze, keine Vorliebe."}),"\n",(0,t.jsx)(n.h3,{id:"die-verifizierung-ist-substanziell-nicht-theatralisch",children:"Die Verifizierung ist substanziell, nicht theatralisch"}),"\n",(0,t.jsx)(n.p,{children:'Verify pr\xfcft, indem sie den Code liest und dem Protokoll gegen\xfcberstellt, nicht indem sie das System ausf\xfchrt. Das ist statische Verifizierung: Sie best\xe4tigt, dass eine Schutzma\xdfnahme im Code vorhanden und korrekt ist, und weist nicht nach, dass die Ma\xdfnahme zur Laufzeit einem Angriff standh\xe4lt. Deshalb ist "Cannot tell from the code" ein legitimes Urteil, kein Fehlschlag, der sich hinter einem bestandenen Ergebnis versteckt. Wenn der Beleg nicht im Code steckt (weil er von der Konfiguration abh\xe4ngt oder von einem Pfad, den der Agent nicht lesen kann), sagt SDH das, statt zu raten.'}),"\n",(0,t.jsx)(n.h3,{id:"determinismus-ist-begrenzt-und-benannt",children:"Determinismus ist begrenzt und benannt"}),"\n",(0,t.jsxs)(n.p,{children:["Der Gro\xdfteil von SDH beruht auf dem Schlussfolgern des Agenten, und genau das erm\xf6glicht seinen Kontextbezug. Determinismus ist den deterministischen Engines vorbehalten: den Pr\xfcfprogrammen, die eine Spezialisierung mitbringen kann (",(0,t.jsx)(n.code,{children:"\xa7VII"}),"), und der Tracking-Engine (",(0,t.jsx)(n.code,{children:"\xa7XI"}),"). Das Dokument verwischt diese Grenze nicht. Wo ein Ergebnis deterministisch ist, ist es das Ergebnis eines Programms. Wo es erschlossen ist, ist es die Lesart des Codes durch den Agenten, und der Nutzer hat das letzte Wort."]}),"\n",(0,t.jsx)(n.h3,{id:"kosten-und-skalierung",children:"Kosten und Skalierung"}),"\n",(0,t.jsxs)(n.p,{children:["Ein vollst\xe4ndiger Durchlauf verbraucht viele Tokens. Die manuellen Modi (",(0,t.jsx)(n.code,{children:"\xa7VI"}),", ",(0,t.jsx)(n.code,{children:"\xa7VIII"}),") gibt es unter anderem, damit die Kosten im Verh\xe4ltnis zum Anliegen stehen."]}),"\n",(0,t.jsx)(n.h3,{id:"der-nutzer-hat-das-letzte-wort",children:"Der Nutzer hat das letzte Wort"}),"\n",(0,t.jsx)(n.p,{children:"SDH l\xe4sst den Menschen entscheiden, ob etwas umbenannt oder behoben wurde, und die Freigabe seiner Code\xe4nderungen bleibt dort, wo der Nutzer seinen Agenten ohnehin steuert: im Berechtigungsmodus, in dem er ihn ausf\xfchrt. Die Methodik schl\xe4gt vor und verifiziert. Sie setzt sich nicht \xfcber den Menschen hinweg."}),"\n",(0,t.jsx)(n.h3,{id:"einw\xe4nde-und-antworten",children:"Einw\xe4nde und Antworten"}),"\n",(0,t.jsx)(n.p,{children:"Ein fairer Skeptiker wird mehrere Einw\xe4nde erheben. Die gewichtigen verdienen es, in ihren eigenen Worten gestellt zu werden."}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:'"Ist das nicht einfach ein statisches Analysetool mit angeflanschtem LLM?"'})," Nein. Ein statisches Analysetool f\xfchrt standardm\xe4\xdfig jede Regel aus, die es hat. SDH erkennt zuerst, was das System ist, greift dann zum relevanten Wissen (",(0,t.jsx)(n.code,{children:"\xa7II"}),", ",(0,t.jsx)(n.code,{children:"\xa7VII"}),") und ",(0,t.jsx)(n.em,{children:"bettet"})," ein deterministisches Pr\xfcfprogramm nur dort ein, wo eine Risikoklasse ein klares Entscheidungsverfahren hat. Das Schlussfolgern geht vom Kontext aus, der Determinismus ist gezielt."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:'"Ist das nicht einfach eine Sicherheitscheckliste?"'})," Nein. SDH kehrt die Checkliste um: Die Erkennung kommt zuerst, und Wissen wird f\xfcr das herangezogen, was das Projekt tats\xe4chlich tut (",(0,t.jsx)(n.code,{children:"\xa7II"}),", ",(0,t.jsx)(n.code,{children:"\xa7VII"}),")."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:'"Ist das nicht einfach SDD, neu verpackt f\xfcr Sicherheit?"'})," Nein. SDH \xfcbernimmt die Struktur von SDD und kehrt seinen Vertrag um: Autorit\xe4t, Zustandsannahme, Endbedingung und Zielgruppe unterscheiden sich allesamt (",(0,t.jsx)(n.code,{children:"\xa7X"}),"). Dieselbe Maschinerie, entgegengesetzte Richtung."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:'"Halluziniert eine Methode, die auf KI-Schlussfolgerungen beruht, nicht einfach Befunde?"'}),' Das Design schr\xe4nkt das Erfinden ein, statt darauf zu vertrauen, dass sich das Modell benimmt. Detect h\xe4lt nur fest, was der Code belegt ("Erkennen, nicht erfinden", ',(0,t.jsx)(n.code,{children:"\xa7IV"}),'), verify stellt Code und Protokoll gegen\xfcber und darf mit "Cannot tell from the code" antworten (',(0,t.jsx)(n.code,{children:"\xa7XV"}),"), deterministische Pr\xfcfprogramme st\xfctzen die entscheidbaren F\xe4lle (",(0,t.jsx)(n.code,{children:"\xa7VII"}),"), und der Nutzer hat das letzte Wort. Das macht den Agenten nicht unfehlbar, aber es macht seine Aussagen \xfcberpr\xfcfbar."]}),"\n",(0,t.jsx)(n.p,{children:"Eine Anmerkung zur Einordnung. SDH wird hier unabh\xe4ngig von seiner Referenzimplementierung definiert. Die f\xfcnf Phasen, die vom Risiko her formulierten Sicherheitsprinzipien, das Abgleichen statt nur Anh\xe4ngen und seine Abschlie\xdfbarkeit, das Wissen per Prompt bei Bedarf, der pr\xe4ventive Modus, die Nachverfolgung mit Identit\xe4t \xfcber den Namen und die ausschlie\xdflich defensive Grenze sind die Methodik. Ein anderes Team k\xf6nnte sie in einem anderen Stack und einem anderen Agenten-\xd6kosystem umsetzen, und das Ergebnis w\xe4re trotzdem SDH. Lagune ist sein Nachweis, nicht seine Definition."}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"xvi-fallstricke-und-wie-sdh-sie-strukturell-vermeidet",children:"XVI. Fallstricke und wie SDH sie strukturell vermeidet"}),"\n",(0,t.jsx)(n.p,{children:"Methodiken dieser Familie teilen eine bekannte Reihe von Fehlermustern. Die Antwort von SDH auf die meisten davon ist strukturell, in den Workflow eingebaut, statt der Disziplin \xfcberlassen."}),"\n",(0,t.jsxs)(n.table,{children:[(0,t.jsx)(n.thead,{children:(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.th,{children:"Fallstrick"}),(0,t.jsx)(n.th,{children:"Das Problem"}),(0,t.jsx)(n.th,{children:"Die strukturelle Antwort von SDH"})]})}),(0,t.jsxs)(n.tbody,{children:[(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Verrottende Spezifikation, veralteter Backlog"}),(0,t.jsx)(n.td,{children:"Artefakte sammeln tote Eintr\xe4ge an, denen niemand traut"}),(0,t.jsxs)(n.td,{children:["Abgleichen statt nur anh\xe4ngen (",(0,t.jsx)(n.code,{children:"\xa7V"}),"): Jeder Lauf pr\xfcft jeden Eintrag neu und entfernt, was behoben ist"]})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Falsche Sicherheit, scheinbar bestanden"}),(0,t.jsx)(n.td,{children:"Man nimmt an, eine vorhandene Schutzma\xdfnahme schlie\xdfe das Risiko"}),(0,t.jsxs)(n.td,{children:['Verify stellt Code und Protokoll gegen\xfcber, sodass "Risk not closed" und "Cannot tell" vollwertige Urteile sind (',(0,t.jsx)(n.code,{children:"\xa7IV"}),", ",(0,t.jsx)(n.code,{children:"\xa7XV"}),")"]})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Checklistenflut"}),(0,t.jsx)(n.td,{children:"Generische Punkte verdecken das eine Risiko, auf das es ankommt"}),(0,t.jsxs)(n.td,{children:["Kontextbezogen statt generisch, mit Prompt bei Bedarf, der nur l\xe4dt, was der Umfang verlangt (",(0,t.jsx)(n.code,{children:"\xa7VII"}),")"]})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Werkzeug-Lock-in"}),(0,t.jsx)(n.td,{children:"Die Methode ist fest an einen Anbieter oder Agenten geschwei\xdft"}),(0,t.jsxs)(n.td,{children:["Agentenunabh\xe4ngiger Tr\xe4ger: Der Sicherheitskern wird einmal geschrieben, und seine Auslieferung an jeden Agenten enth\xe4lt keine Sicherheitslogik (",(0,t.jsx)(n.code,{children:"\xa7XII"}),")"]})]}),(0,t.jsxs)(n.tr,{children:[(0,t.jsx)(n.td,{children:"Die Endlosschleife"}),(0,t.jsx)(n.td,{children:"Der Backlog schlie\xdft sich nie, die Arbeit ruht nie"}),(0,t.jsxs)(n.td,{children:["Abschlie\xdfbarkeit und der Ruhezustand (",(0,t.jsx)(n.code,{children:"\xa7V"}),")"]})]})]})]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Tabelle 4."})," Bekannte Fallstricke in dieser Methodikfamilie und die strukturelle Antwort von SDH auf jeden davon."]}),"\n",(0,t.jsx)(n.p,{children:"Darum geht es: den Fallstrick zu benennen und auf den Mechanismus zu zeigen. Das sind keine Mahnungen zur Vorsicht, sondern Eigenschaften des Workflows."}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"xvii-k\xfcnftige-arbeiten",children:"XVII. K\xfcnftige Arbeiten"}),"\n",(0,t.jsx)(n.p,{children:"Die Methodik und ihre Referenzimplementierung haben klare n\xe4chste Schritte."}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Den Wissenskatalog erweitern:"}),"\nJede Erg\xe4nzung beh\xe4lt die Form aus ",(0,t.jsx)(n.code,{children:"\xa7VII"}),": eine Wissensdatei und eine Katalogzeile, kein neuer Befehl. Den Weg f\xfcr Nutzer gibt es dort bereits: Der Nutzer verdichtet seine eigenen Spezialisierungen bei Bedarf. Weitere integrierte Sprachen, Laufzeitumgebungen und Risikoklassen, jeweils in einer Kategorie, sind die Richtung auf Seiten des Maintainers, und die Spezialisierungen werden sich voraussichtlich weiterentwickeln."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Mehr deterministische Pr\xfcfprogramme:"}),"\nWo eine Risikoklasse ein klares Entscheidungsverfahren hat, kann eine Spezialisierung ein deterministisches Pr\xfcfprogramm mitbringen, das das Schlussfolgern des Agenten in einem wiederholbaren Urteil verankert. Das auf weitere Risikoklassen auszudehnen, ist eine naheliegende Richtung."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Empirische Evaluation:"}),"\nDie wichtigste offene Frage ist die gemessene Wirksamkeit: die Qualit\xe4t der Abschl\xfcsse und die Rate falscher Urteile in realen Codebasen. Eine Studie der Sicherheitsergebnisse von SDH steht noch aus, und die Aussagen hier sind entsprechend eingegrenzt."]}),"\n"]}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"xviii-fazit",children:"XVIII. Fazit"}),"\n",(0,t.jsx)(n.p,{children:"KI-gest\xfctzte Entwicklung hat eine Sicherheitsl\xfccke ge\xf6ffnet, die generische Checklisten nicht f\xfcllen k\xf6nnen, weil das Risiko, auf das es ankommt, davon abh\xe4ngt, was ein System tats\xe4chlich tut, und weil die Person, die es ausliefert, vielleicht nicht wei\xdf, wonach sie fragen soll. SDH schlie\xdft diese L\xfccke mit einem kontextbezogenen, ausschlie\xdflich defensiven und abschlie\xdfbaren Workflow, in dem das Sicherheitswissen in der Methodik und ihren bei Bedarf geladenen Spezialisierungen steckt, einer Grundlage, auf der jeder Nutzer aufbauen kann. Es erkennt den tats\xe4chlichen Kontext des Systems, priorisiert die Risiken, die dieser Kontext mit sich bringt, setzt Korrekturen sorgf\xe4ltig um und verifiziert jede einzelne, dann tr\xe4gt es aus, was es abgeschlossen hat, sodass jeder Befund einen Endzustand erreicht. Dieselbe Verteidigung l\xe4uft au\xdferdem pr\xe4ventiv mit, w\xe4hrend neue Arbeit entsteht, sodass geschlossen bleibt, was der Workflow schlie\xdft. Es passt sich jedem Entwicklungsstand in jedem Stack an und erweitert das Wissen der Entwickler, statt die Menschen und Werkzeuge zu ersetzen, die diese Arbeit bereits leisten."}),"\n",(0,t.jsx)(n.p,{children:"Lagune ist der Nachweis, doch der Beitrag ist die Konvention. SDH versteht sich als der grundlegende Sicherheits-Workflow f\xfcr das Zeitalter der Entwicklung mit KI, den andere \xfcbernehmen, verfeinern und in ihren eigenen Stacks umsetzen k\xf6nnen."}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"literatur",children:"Literatur"}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"[1]"}),' D. B. Piskala, "Spec-Driven Development: From Code to Contract in the Age of AI Coding Assistants," arXiv preprint arXiv:2602.00180v1 [cs.SE], Jan. 2026. (Submitted to AIWare 2026.) [Online]. Available: ',(0,t.jsx)(n.a,{href:"https://arxiv.org/abs/2602.00180",children:"https://arxiv.org/abs/2602.00180"})]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"[2]"}),' GitHub, "Spec Kit: Toolkit for Spec-Driven Development." [Online]. Available: ',(0,t.jsx)(n.a,{href:"https://github.com/github/spec-kit",children:"https://github.com/github/spec-kit"}),". Accessed: 2026."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"[3]"}),' Fission AI, "OpenSpec: Spec-Driven Development for AI Coding Assistants." [Online]. Available: ',(0,t.jsx)(n.a,{href:"https://github.com/Fission-AI/OpenSpec",children:"https://github.com/Fission-AI/OpenSpec"}),". Accessed: 2026."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"[4]"}),' B. Chess and G. McGraw, "Static Analysis for Security," IEEE Security & Privacy, vol. 2, no. 6, pp. 76-79, 2004, doi: 10.1109/MSP.2004.111.']}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"[5]"}),' OWASP Foundation, "Source Code Analysis Tools." [Online]. Available: ',(0,t.jsx)(n.a,{href:"https://owasp.org/www-community/Source_Code_Analysis_Tools",children:"https://owasp.org/www-community/Source_Code_Analysis_Tools"}),". Accessed: 2026."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"[6]"}),' OWASP Foundation, "OWASP Top 10:2021." [Online]. Available: ',(0,t.jsx)(n.a,{href:"https://owasp.org/Top10/",children:"https://owasp.org/Top10/"}),". Accessed: 2026."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"[7]"}),' MITRE, "Common Weakness Enumeration (CWE)." [Online]. Available: ',(0,t.jsx)(n.a,{href:"https://cwe.mitre.org/",children:"https://cwe.mitre.org/"}),". Accessed: 2026."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"[8]"}),' N. Perry, M. Srivastava, D. Kumar, and D. Boneh, "Do Users Write More Insecure Code with AI Assistants?," in Proc. ACM SIGSAC Conf. on Computer and Communications Security (CCS \'23), 2023, pp. 2785-2799, doi: 10.1145/3576915.3623157. [Online]. Available: ',(0,t.jsx)(n.a,{href:"https://arxiv.org/abs/2211.03622",children:"https://arxiv.org/abs/2211.03622"})]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"[9]"}),' J. Davis and contributors, "safe-regex: Detect Possibly Catastrophic, Exponential-Time Regular Expressions." [Online]. Available: ',(0,t.jsx)(n.a,{href:"https://github.com/davisjam/safe-regex",children:"https://github.com/davisjam/safe-regex"}),". Accessed: 2026."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"[10]"}),' D. Soshnikov, "regexp-tree: Regular Expressions Processor in JavaScript." [Online]. Available: ',(0,t.jsx)(n.a,{href:"https://github.com/DmitrySoshnikov/regexp-tree",children:"https://github.com/DmitrySoshnikov/regexp-tree"}),". Accessed: 2026."]}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"[11]"}),' T. Jenkinson, "redos-detector: A CLI and Library to Score How Vulnerable a Regex Pattern Is to ReDoS Attacks." [Online]. Available: ',(0,t.jsx)(n.a,{href:"https://github.com/tjenkinson/redos-detector",children:"https://github.com/tjenkinson/redos-detector"}),". Accessed: 2026."]}),"\n",(0,t.jsx)(n.hr,{}),"\n",(0,t.jsx)(n.h2,{id:"anhang-a-die-prinzipien-im-wortlaut",children:"Anhang A: die Prinzipien im Wortlaut"}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Standardm\xe4\xdfig sicher, in verst\xe4ndlicher Sprache, f\xfcr alle gleicherma\xdfen:"}),"\nJeder Standardwert, jede Meldung und jede Korrektur muss von Haus aus sicher und f\xfcr jeden Nutzer verst\xe4ndlich sein, ob Entwickler oder nicht. Keine Nutzergruppe wird gegen\xfcber einer anderen bevorzugt."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Kontextbezogen statt generisch:"}),"\nJede Phase muss vom Kontext ausgehen, den detect erkannt hat, und mit dem arbeiten, was das System tats\xe4chlich tut. Bevorzuge Empfehlungen, die auf diesen Kontext zugeschnitten sind, gegen\xfcber generischen Checklisten. Das Sicherheitswissen steckt in der Spezifikation und ihren bei Bedarf geladenen Spezialisierungen und erweitert, was der Nutzer mitbringt."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Flexibel statt starr:"}),"\nSDH passt sich dem Projekt und dem Nutzer an. Prinzipien, Anforderungen und Empfehlungen sind Ausgangspunkte, kein fester Vertrag. Lass den Nutzer alles umformulieren, streichen, erg\xe4nzen oder eingrenzen. Flexibilit\xe4t schw\xe4cht nie die standardm\xe4\xdfig sichere Grundlage, sie l\xe4sst den Nutzer nur bestimmen, wie sie angewendet wird."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Abgleichen statt nur anh\xe4ngen:"}),"\nArtefakte sind lebendige Dokumente, keine Logs. Wenn eine Phase erneut l\xe4uft, gleiche jeden vorhandenen Eintrag mit dem aktuellen Stand ab: Behalte, was noch gilt, schreibe um, was sich ge\xe4ndert hat, und entferne, was nicht mehr zutrifft. Der Abschluss ist derselbe Abgleich, an seinem Ende angekommen."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Ausschlie\xdflich defensiv:"}),"\nSDH auditiert, h\xe4rtet und verifiziert. Es erzeugt nie offensive Werkzeuge, Exploits f\xfcr b\xf6swillige Zwecke oder Techniken zur Umgehung von Erkennung, um Schaden anzurichten. Dual-Use-Sicherheitsinhalte sind nur in einem klar defensiven, autorisierten Rahmen zul\xe4ssig."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Spec-first, agentengesteuert, auf Sicherheit ausgerichtet:"}),"\nBaue den Workflow auf einer bew\xe4hrten Struktur auf: Vorlagen, Befehle, \xfcbergeordnete Sicherheitsprinzipien und ein Agent, der die Phasen ausf\xfchrt. Setze diese Struktur mit defensivem Zweck neu um."]}),"\n"]})]})}function u(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(l,{...e})}):l(e)}}}]);